class BuildActionEnvironment(AtpBlueprint,AtpBlueprintable):
    """
    This meta-class represents the ability to specify a build action environment.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BUILD-ACTION-ENVIRONMENT'
        self._node = etree.Element('BUILD-ACTION-ENVIRONMENT')
        self.__sdgs = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__sdgs, '{*}SDGS/*', Sdg, file, 'sdgs', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_sdgs(self) -> list[Sdg]:
        return list(self.__sdgs.keys())

    def __bind_sdg(self, value: Sdg) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__sdgs.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, Sdg) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Sdg or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'Sdg_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_sdg_at_index(self, index: int, value: Sdg) -> None:
        """
        Adds a single value to the sdgs at the given index
        """
        if value is not None:
            self.__bind_sdg(value)
            AutosarNode._insert_at_index(self.__sdgs, value, index)
            self._sync_add_to_merge_target(value)

    def add_sdg(self, value: Sdg) -> None:
        """
        Adds a single value to the sdgs
        """
        if value is not None:
            self.__bind_sdg(value)
            self.__sdgs[value] = None
            self._sync_add_to_merge_target(value)

    def set_sdgs(self, values: list[Sdg]) -> None:
        """
        Adds a list of ref value to the sdgs
        """
        for value in values:
            self.add_sdg(value)

    def remove_sdg(self, value: Sdg) -> None:
        """
        Removes a single value from sdgs
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_sdgs(self, values: list[Sdg]) -> None:
        """
        Removes a list of value from sdgs
        """
        for value in values:
            self.remove_sdg(value)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_Sdg(self, name: str=None) -> Sdg:
        """
        Creates a new Sdg under the BuildActionEnvironment.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Sdg_obj = Sdg()
        if isinstance(Sdg_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Sdg_obj.name = name if isinstance(Sdg_obj, Referrable) else None
        self.add_sdg(Sdg_obj)
        if isinstance(Sdg_obj, Referrable):
            Sdg_obj.set_shortName(name)
        return Sdg_obj

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the BuildActionEnvironment.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__sdgs)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__sdgs:
            return 'sdgs'
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'sdgs':
            self.__sdgs[child] = None
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'sdgs':
            self.__sdgs.pop(child, None)
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of BuildActionEnvironment node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_AtpBlueprint()
        super()._save_AtpBlueprintable()
        self._save_child_collection('SDGS', None, self.__sdgs, self._insert_after_tags + ['SHORT-NAME-PATTERN', 'BLUEPRINT-POLICYS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['SDGS', 'SHORT-NAME-PATTERN', 'BLUEPRINT-POLICYS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

class BuildActionManifest(ARElement,AtpBlueprint,AtpBlueprintable):
    """
    This meta-class represents the ability to specify a manifest for processing artifacts. An example use case is the processing of ECUC parameter values.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BUILD-ACTION-MANIFEST'
        self._node = etree.Element('BUILD-ACTION-MANIFEST')
        self.__startActions = {}
        self.__tearDownActions = {}
        self.__buildActions = {}
        self.__buildActionEnvironments = {}
        self.__dynamicActions = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__buildActions, '{*}BUILD-ACTIONS/*', BuildAction, file, 'buildActions', refCounter)
        refCounter = self._build_child_collection(self.__buildActionEnvironments, '{*}BUILD-ACTION-ENVIRONMENTS/*', BuildActionEnvironment, file, 'buildActionEnvironments', refCounter)
