class MixedContentForOverviewParagraph(ARObject):
    """
    This is the text model of a restricted paragraph item within a documentation. Such restricted paragraphs are used mainly for overview items, e.g. desc.
    """
    def __init__(self):
        super().__init__()
        self.__sups = None
        self.__subs = None
        self.__brs = {}
        self.__fts = {}
        self.__traces = {}
        self.__tts = {}
        self.__xrefs = {}
        self.__xrefTargets = {}
        self.__es = {}
        self.__ies = {}

        self.__mixedtext = None

