class TraceableTable(Identifiable,Paginateable,Traceable):
    """
    This meta-class represents a table which can be referenced in order to establish requirements tracing. It supports specific kinds of tracing such as requirements / constraints., , The following approach applies:, , * [ARMetaClassRole{shortName}{Referrable}]: represents the tag for tracing, * [ARMetaClassRole{longName}{MultilanguageReferrable}]: represents the headline, * [ARMetaClassRole{category}{Identifiable}]: represents the kind of the tagged table
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TRACEABLE-TABLE'
        self._node = etree.Element('TRACEABLE-TABLE')
        self.__table = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__table = self._build_single_child('{*}TABLE', Table, file, 'table')
        return self

    def get_table(self) -> Table:
        return self.__table

    def set_table(self, value: Table) -> None:
        """
        Adds a single value to the table
        """
        if value is not None:
            if isinstance(value, Table) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Table or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__table = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'Table_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__table is not None:
            self.__table._detach_from_parent()
            self.__table = None
        XDT.mark_dirty(self.__table, self)

    def new_Table(self, name: str=None) -> Table:
        """
        Creates a new Table under the TraceableTable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Table_obj = Table()
        if isinstance(Table_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Table_obj.name = name if isinstance(Table_obj, Referrable) else None
        self.set_table(Table_obj)
        if isinstance(Table_obj, Referrable):
            Table_obj.set_shortName(name)
        return Table_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__table is not None:
            children.append(self.__table)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__table is child:
            return 'table'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'table':
            if self.__table is None:
                self.__table = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'table':
            if self.__table is child:
                self.__table = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values


    def _save_contents(self):
        """
        Saves the content of TraceableTable node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        super()._save_Paginateable()
        super()._save_Traceable()
        self._save_single_child('TABLE', self.__table, self._insert_after_tags + ['TRACE-REFS', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

class TraceReferrable(MultilanguageReferrable):
    """
    This meta class is intended to add the category to the subclasses of Traceable. , , Even if the model seems to be a bit awkward, it ensures backwards compatibility of the schema., , This approach allows to have subclasses of Traceable which are either Identifiable or only Referrable while still maintaining the consistent sequence of shortName, longName, category.
    """
    def __init__(self):
        super().__init__()




    def _save_TraceReferrable(self):
        """
        Saves the content of TraceReferrable node
        """
        super()._save_MultilanguageReferrable()

