class MlFigure(Paginateable):
    """
    This metaclass represents the ability to embed a figure.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ML-FIGURE'
        self._node = etree.Element('ML-FIGURE')
        self.__frame = None
        self.__helpEntry = None
        self.__pgwide = None
        self.__figureCaption = None
        self.__lGraphics = {}
        self.__verbatim = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__frame = self._read_xml_attribute('FRAME', FrameEnum.get)
        self.__helpEntry = self._read_xml_attribute('HELP-ENTRY', datatype_utils.get_string_value)
        self.__pgwide = self._read_xml_attribute('PGWIDE', PgwideEnum.get)

        refCounter = 0
        self.__figureCaption = self._build_single_child('{*}FIGURE-CAPTION', Caption, file, 'figureCaption')
        refCounter = self._build_child_collection(self.__lGraphics, '{*}L-GRAPHIC', LGraphic, file, 'lGraphics', refCounter)
        self.__verbatim = self._build_single_child('{*}VERBATIM', MultiLanguageVerbatim, file, 'verbatim')
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_frame(self) -> FrameEnum:
        return self.__frame

    def set_frame(self, value: FrameEnum) -> None:
        self.__frame = value
        XDT.mark_attribute_dirty('frame', self)

    def get_helpEntry(self) -> str:
        return self.__helpEntry

    def set_helpEntry(self, value: str) -> None:
        self.__helpEntry = value
        XDT.mark_attribute_dirty('helpEntry', self)

    def get_pgwide(self) -> PgwideEnum:
        return self.__pgwide

    def set_pgwide(self, value: PgwideEnum) -> None:
        self.__pgwide = value
        XDT.mark_attribute_dirty('pgwide', self)

    def get_figureCaption(self) -> Caption:
        return self.__figureCaption

    def set_figureCaption(self, value: Caption) -> None:
        """
        Adds a single value to the figureCaption
        """
        if value is not None:
            if isinstance(value, Caption) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Caption or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__figureCaption = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'Caption_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__figureCaption is not None:
            self.__figureCaption._detach_from_parent()
            self.__figureCaption = None
        XDT.mark_dirty(self.__figureCaption, self)

    def get_lGraphics(self) -> list[LGraphic]:
        return list(self.__lGraphics.keys())

    def __bind_lGraphic(self, value: LGraphic) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__lGraphics.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, LGraphic) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of LGraphic or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'LGraphic_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['l', 'timestamp', 'checksum'])

    def add_lGraphic_at_index(self, index: int, value: LGraphic) -> None:
        """
        Adds a single value to the lGraphics at the given index
        """
        if value is not None:
            self.__bind_lGraphic(value)
            AutosarNode._insert_at_index(self.__lGraphics, value, index)
            self._sync_add_to_merge_target(value)

    def add_lGraphic(self, value: LGraphic) -> None:
        """
        Adds a single value to the lGraphics
        """
        if value is not None:
            self.__bind_lGraphic(value)
            self.__lGraphics[value] = None
            self._sync_add_to_merge_target(value)

    def set_lGraphics(self, values: list[LGraphic]) -> None:
        """
        Adds a list of ref value to the lGraphics
        """
        for value in values:
            self.add_lGraphic(value)

    def remove_lGraphic(self, value: LGraphic) -> None:
        """
        Removes a single value from lGraphics
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_lGraphics(self, values: list[LGraphic]) -> None:
        """
        Removes a list of value from lGraphics
        """
        for value in values:
            self.remove_lGraphic(value)

    def get_verbatim(self) -> MultiLanguageVerbatim:
        return self.__verbatim

    def set_verbatim(self, value: MultiLanguageVerbatim) -> None:
        """
        Adds a single value to the verbatim
        """
        if value is not None:
            if isinstance(value, MultiLanguageVerbatim) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultiLanguageVerbatim or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__verbatim = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'MultiLanguageVerbatim_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__verbatim is not None:
            self.__verbatim._detach_from_parent()
            self.__verbatim = None
        XDT.mark_dirty(self.__verbatim, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_FigureCaption(self, name: str=None) -> Caption:
        """
        Creates a new Caption under the MlFigure.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Caption_obj = Caption()
        if isinstance(Caption_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Caption_obj.name = name if isinstance(Caption_obj, Referrable) else None
        self.set_figureCaption(Caption_obj)
        if isinstance(Caption_obj, Referrable):
            Caption_obj.set_shortName(name)
        return Caption_obj

    def new_LGraphic(self, name: str=None) -> LGraphic:
        """
        Creates a new LGraphic under the MlFigure.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        LGraphic_obj = LGraphic()
        if isinstance(LGraphic_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        LGraphic_obj.name = name if isinstance(LGraphic_obj, Referrable) else None
        self.add_lGraphic(LGraphic_obj)
        if isinstance(LGraphic_obj, Referrable):
            LGraphic_obj.set_shortName(name)
        return LGraphic_obj

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the MlFigure.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def new_Verbatim(self, name: str=None) -> MultiLanguageVerbatim:
        """
        Creates a new MultiLanguageVerbatim under the MlFigure.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        MultiLanguageVerbatim_obj = MultiLanguageVerbatim()
        if isinstance(MultiLanguageVerbatim_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        MultiLanguageVerbatim_obj.name = name if isinstance(MultiLanguageVerbatim_obj, Referrable) else None
        self.set_verbatim(MultiLanguageVerbatim_obj)
        if isinstance(MultiLanguageVerbatim_obj, Referrable):
            MultiLanguageVerbatim_obj.set_shortName(name)
        return MultiLanguageVerbatim_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__figureCaption is not None:
            children.append(self.__figureCaption)
        children.extend(self.__lGraphics)
        if self.__verbatim is not None:
            children.append(self.__verbatim)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__figureCaption is child:
            return 'figureCaption'
        if child in self.__lGraphics:
            return 'lGraphics'
        if self.__verbatim is child:
            return 'verbatim'
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'figureCaption':
            if self.__figureCaption is None:
                self.__figureCaption = child
        elif containment_slot == 'lGraphics':
            self.__lGraphics[child] = None
        elif containment_slot == 'verbatim':
            if self.__verbatim is None:
                self.__verbatim = child
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'figureCaption':
            if self.__figureCaption is child:
                self.__figureCaption = None
        elif containment_slot == 'lGraphics':
            self.__lGraphics.pop(child, None)
        elif containment_slot == 'verbatim':
            if self.__verbatim is child:
                self.__verbatim = None
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Frame'] = self.__frame
        property_values['HelpEntry'] = self.__helpEntry
        property_values['Pgwide'] = self.__pgwide
        return property_values


    def _save_contents(self):
        """
        Saves the content of MlFigure node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Paginateable()
        self._save_single_child('FIGURE-CAPTION', self.__figureCaption, self._insert_after_tags + ['KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_xml_attribute('FRAME', 'frame', self.__frame.literal if self.__frame is not None else None)
        self._save_xml_attribute('HELP-ENTRY', 'helpEntry', str(self.__helpEntry) if self.__helpEntry is not None else None)
        self._save_xml_attribute('PGWIDE', 'pgwide', self.__pgwide.literal if self.__pgwide is not None else None)
        self._save_child_collection(None, None, self.__lGraphics, self._insert_after_tags + ['FIGURE-CAPTION', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_single_child('VERBATIM', self.__verbatim, self._insert_after_tags + ['L-GRAPHIC', 'FIGURE-CAPTION', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['VERBATIM', 'L-GRAPHIC', 'FIGURE-CAPTION', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])

class LGraphic(LanguageSpecific):
    """
    This meta-class represents the figure in one particular language.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'L-GRAPHIC'
        self._node = etree.Element('L-GRAPHIC')
        self.__graphic = None
        self.__map = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__graphic = self._build_single_child('{*}GRAPHIC', Graphic, file, 'graphic')
        self.__map = self._build_single_child('{*}MAP', Map, file, 'map')
        return self

    def get_graphic(self) -> Graphic:
        return self.__graphic

    def set_graphic(self, value: Graphic) -> None:
        """
        Adds a single value to the graphic
        """
