class SdgContents(ARObject):
    """
    This meta-class represents the possible contents of a special data group. It can be an arbitrary mix of references, of primitive special data and nested special data groups.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SDG-CONTENTS'
        self._node = etree.Element('SDG-CONTENTS')
        self.__sdxs = {}
        self.__sdxfs = {}
        self.__sds = {}
        self.__sdgs = {}
        self.__sdfs = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__sdxfs, '{*}SDXF', ReferrableRefConditional, file, 'sdxfs', refCounter)
        refCounter = self._build_child_collection(self.__sds, '{*}SD', Sd, file, 'sds', refCounter)
        refCounter = self._build_child_collection(self.__sdgs, '{*}SDG', Sdg, file, 'sdgs', refCounter)
        refCounter = self._build_child_collection(self.__sdfs, '{*}SDF', Sdf, file, 'sdfs', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__sdxs = self._resolve_reference_list('{*}SDX-REF', self.__sdxs)

    def get_sdxs(self) -> list[Referrable]:
        return list(self.__sdxs.keys())

    def __bind_sdx(self, value: Referrable) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__sdxs.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, Referrable) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Referrable or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_sdx(self, value: Referrable) -> None:
        """
        Adds a single value to the sdxs
        """
        if value is not None:
            self.__bind_sdx(value)
            self.__sdxs[value] = None

    def set_sdxs(self, values: list[Referrable]) -> None:
        """
        Adds a list of ref value to the sdxs
        """
        for value in values:
            self.add_sdx(value)

    def remove_sdx(self, value: Referrable) -> None:
        """
        Removes a single value from sdxs
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__sdxs.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_sdxs(self, values: list[Referrable]) -> None:
        """
        Removes a list of value from sdxs
        """
        for value in values:
            self.remove_sdx(value)

    def get_sdxfs(self) -> list[ReferrableRefConditional]:
        return list(self.__sdxfs.keys())

    def __bind_sdxf(self, value: ReferrableRefConditional) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__sdxfs.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ReferrableRefConditional) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ReferrableRefConditional or its sub-classes'.format(value))

        value._detach_from_parent()
