class PortPrototypeBlueprintInitValue(ARObject):
    """
    This meta-class represents the ability to express init values in PortPrototypeBlueprints. These init values act as a kind of blueprint from which for example proper ComSpecs can be derived.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PORT-PROTOTYPE-BLUEPRINT-INIT-VALUE'
        self._node = etree.Element('PORT-PROTOTYPE-BLUEPRINT-INIT-VALUE')
        self.__dataPrototype = None
        self.__value = None
        self.__value_childTypes = {'APPLICATION-RULE-BASED-VALUE-SPECIFICATION': 'ApplicationRuleBasedValueSpecification', 'COMPOSITE-RULE-BASED-VALUE-SPECIFICATION': 'CompositeRuleBasedValueSpecification', 'NUMERICAL-RULE-BASED-VALUE-SPECIFICATION': 'NumericalRuleBasedValueSpecification', 'APPLICATION-VALUE-SPECIFICATION': 'ApplicationValueSpecification', 'ARRAY-VALUE-SPECIFICATION': 'ArrayValueSpecification', 'RECORD-VALUE-SPECIFICATION': 'RecordValueSpecification', 'APPLICATION-ASSOC-MAP-VALUE-SPECIFICATION': 'ApplicationAssocMapValueSpecification', 'CONSTANT-REFERENCE': 'ConstantReference', 'NOT-AVAILABLE-VALUE-SPECIFICATION': 'NotAvailableValueSpecification', 'NUMERICAL-VALUE-SPECIFICATION': 'NumericalValueSpecification', 'REFERENCE-VALUE-SPECIFICATION': 'ReferenceValueSpecification', 'TEXT-VALUE-SPECIFICATION': 'TextValueSpecification', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__value = self._build_single_child('{*}VALUE/*', self.__value_childTypes, file, 'value')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__dataPrototype = self._resolve_single_reference('{*}DATA-PROTOTYPE-REF', self.__dataPrototype)

    def get_dataPrototype(self) -> AutosarDataPrototype:
        return self.__dataPrototype

    def set_dataPrototype(self, value: AutosarDataPrototype) -> None:
        """
        Adds a single value to the dataPrototype
        """
        if value is not None:
            if isinstance(value, AutosarDataPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AutosarDataPrototype or its sub-classes'.format(value))
            if self.__dataPrototype is not None and self.__dataPrototype.is_proxy() is False:
                self.__dataPrototype.referenced_by.remove(self)
            self.__dataPrototype = value
            value.referenced_by.add(self)
        elif self.__dataPrototype is not None:
            if self.__dataPrototype.is_proxy() is False:
                self.__dataPrototype.referenced_by.remove(self)
            self.__dataPrototype = None
        XDT.mark_dirty(self.__dataPrototype, self)

    def get_value(self) -> ValueSpecification:
        return self.__value

    def set_value(self, value: ValueSpecification) -> None:
        """
        Adds a single value to the value
        """
        if value is not None:
            if isinstance(value, ValueSpecification) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ValueSpecification or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__value = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'ValueSpecification_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__value is not None:
            self.__value._detach_from_parent()
            self.__value = None
        XDT.mark_dirty(self.__value, self)

