        if child is None:
            return
        if containment_slot == 'condition':
            if self.__condition is None:
                self.__condition = child
        elif containment_slot == 'attributeTailorings':
            self.__attributeTailorings[child] = None
        elif containment_slot == 'constraintTailorings':
            self.__constraintTailorings[child] = None
        elif containment_slot == 'sdgTailorings':
            self.__sdgTailorings[child] = None
