        self.__resultingRptSwPrototypingAccess = self._build_single_child('{*}RESULTING-RPT-SW-PROTOTYPING-ACCESS', RptSwPrototypingAccess, file, 'resultingRptSwPrototypingAccess')
        self.__rptImplPolicy = self._build_single_child('{*}RPT-IMPL-POLICY', RptImplPolicy, file, 'rptImplPolicy')
        refCounter = self._build_child_collection(self.__subElements, '{*}SUB-ELEMENTS/*', McDataInstance, file, 'subElements', refCounter)
