class RoleBasedMcDataAssignment(ARObject):
    """
    This meta-class allows to define links that specify logical relationships between single McDataInstances. The details on the existence and semantics of such links are not standardized., , Possible Use Case: , Rapid Prototyping solutions in which additional communication buffers and switches are implemented  in the RTE that allow to switch between the usage of the original and the bypass buffers. The different buffers and the switch can be represented by McDataInstances (in order to be accessed by MC tools) which have relationships to each other.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ROLE-BASED-MC-DATA-ASSIGNMENT'
        self._node = etree.Element('ROLE-BASED-MC-DATA-ASSIGNMENT')
        self.__role = None
        self.__executionContexts = {}
        self.__mcDataInstances = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__role = self._read_scalar_element('ROLE', datatype_utils.get_string_value)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__executionContexts = self._resolve_reference_list('{*}EXECUTION-CONTEXT-REFS/*', self.__executionContexts)
        self.__mcDataInstances = self._resolve_reference_list('{*}MC-DATA-INSTANCE-REFS/*', self.__mcDataInstances)

    def get_role(self) -> str:
        return self.__role

    def set_role(self, value: str) -> None:
        self.__role = value
        XDT.mark_attribute_dirty('role', self)

    def get_executionContexts(self) -> list[RptExecutionContext]:
        return list(self.__executionContexts.keys())

    def __bind_executionContext(self, value: RptExecutionContext) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__executionContexts.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, RptExecutionContext) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RptExecutionContext or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_executionContext(self, value: RptExecutionContext) -> None:
        """
        Adds a single value to the executionContexts
        """
        if value is not None:
            self.__bind_executionContext(value)
            self.__executionContexts[value] = None

    def set_executionContexts(self, values: list[RptExecutionContext]) -> None:
        """
        Adds a list of ref value to the executionContexts
        """
        for value in values:
            self.add_executionContext(value)

    def remove_executionContext(self, value: RptExecutionContext) -> None:
        """
        Removes a single value from executionContexts
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__executionContexts.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_executionContexts(self, values: list[RptExecutionContext]) -> None:
        """
        Removes a list of value from executionContexts
        """
        for value in values:
            self.remove_executionContext(value)

