class RptSupportData(ARObject):
    """
    Root element for rapid prototyping support data related to one Implementation artifact on an ECU, in particular the RTE. , The rapid prototyping support data may reference to elements provided for McSupportData.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RPT-SUPPORT-DATA'
        self._node = etree.Element('RPT-SUPPORT-DATA')
        self.__executionContexts = {}
        self.__rptComponents = {}
        self.__rptServicePoints = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__executionContexts, '{*}EXECUTION-CONTEXTS/*', RptExecutionContext, file, 'executionContexts', refCounter)
        refCounter = self._build_child_collection(self.__rptComponents, '{*}RPT-COMPONENTS/*', RptComponent, file, 'rptComponents', refCounter)
        refCounter = self._build_child_collection(self.__rptServicePoints, '{*}RPT-SERVICE-POINTS/*', RptServicePoint, file, 'rptServicePoints', refCounter)
        return self

    def get_executionContexts(self) -> list[RptExecutionContext]:
        return list(self.__executionContexts.keys())

    def __bind_executionContext(self, value: RptExecutionContext) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__executionContexts.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, RptExecutionContext) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RptExecutionContext or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'RptExecutionContext_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

