class FlatMap(ARElement,AtpBlueprint,AtpBlueprintable):
    """
    Contains a flat list of references to software objects. This list is used to identify instances and to resolve name conflicts. The scope is given by the RootSwCompositionPrototype for which it is used, i.e. it can be applied to a system, system extract or ECU-extract., , An instance of FlatMap may also be used in a preliminary context, e.g. in the scope of a software component before integration into a system. In this case it is not referred by a RootSwCompositionPrototype.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLAT-MAP'
        self._node = etree.Element('FLAT-MAP')
        self.__instances = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__instances, '{*}INSTANCES/*', FlatInstanceDescriptor, file, 'instances', refCounter)
        return self

    def get_instances(self) -> list[FlatInstanceDescriptor]:
        return list(self.__instances.keys())

    def __bind_instance(self, value: FlatInstanceDescriptor) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__instances.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, FlatInstanceDescriptor) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FlatInstanceDescriptor or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'FlatInstanceDescriptor_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_instance_at_index(self, index: int, value: FlatInstanceDescriptor) -> None:
        """
        Adds a single value to the instances at the given index
        """
        if value is not None:
            self.__bind_instance(value)
            AutosarNode._insert_at_index(self.__instances, value, index)
            self._sync_add_to_merge_target(value)

    def add_instance(self, value: FlatInstanceDescriptor) -> None:
        """
        Adds a single value to the instances
        """
        if value is not None:
            self.__bind_instance(value)
            self.__instances[value] = None
            self._sync_add_to_merge_target(value)

    def set_instances(self, values: list[FlatInstanceDescriptor]) -> None:
        """
        Adds a list of ref value to the instances
        """
        for value in values:
            self.add_instance(value)

    def remove_instance(self, value: FlatInstanceDescriptor) -> None:
        """
        Removes a single value from instances
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_instances(self, values: list[FlatInstanceDescriptor]) -> None:
        """
        Removes a list of value from instances
        """
        for value in values:
            self.remove_instance(value)

    def new_Instance(self, name: str=None) -> FlatInstanceDescriptor:
        """
        Creates a new FlatInstanceDescriptor under the FlatMap.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        FlatInstanceDescriptor_obj = FlatInstanceDescriptor()
        if isinstance(FlatInstanceDescriptor_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        FlatInstanceDescriptor_obj.name = name if isinstance(FlatInstanceDescriptor_obj, Referrable) else None
        self.add_instance(FlatInstanceDescriptor_obj)
        if isinstance(FlatInstanceDescriptor_obj, Referrable):
            FlatInstanceDescriptor_obj.set_shortName(name)
        return FlatInstanceDescriptor_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__instances)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__instances:
            return 'instances'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'instances':
            self.__instances[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'instances':
            self.__instances.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of FlatMap node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARElement()
        super()._save_AtpBlueprint()
        super()._save_AtpBlueprintable()
        self._save_child_collection('INSTANCES', None, self.__instances, self._insert_after_tags + ['SHORT-NAME-PATTERN', 'BLUEPRINT-POLICYS', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

