        refCounter = self._build_child_collection(self.__connectors, '{*}CONNECTORS/*', self.__connectors_childTypes, file, 'connectors', refCounter)
        refCounter = self._build_child_collection(self.__instantiationRTEEventProps, '{*}INSTANTIATION-RTE-EVENT-PROPSS/*', self.__instantiationRTEEventProps_childTypes, file, 'instantiationRTEEventProps', refCounter)
