class RunnableEntity(AtpStructureElement,ExecutableEntity):
    """
    A RunnableEntity represents the smallest code-fragment that is provided by an AtomicSwComponentType and are executed under control of the RTE. RunnableEntities are for instance set up to respond to data reception or operation invocation on a server.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RUNNABLE-ENTITY'
        self._node = etree.Element('RUNNABLE-ENTITY')
        self.__canBeInvokedConcurrently = None
        self.__symbol = None
        self.__arguments = {}
        self.__asynchronousServerCallResultPoints = {}
        self.__dataReadAccess = {}
        self.__dataReceivePointByArguments = {}
        self.__dataReceivePointByValues = {}
        self.__dataSendPoints = {}
        self.__dataWriteAccess = {}
        self.__externalTriggeringPoints = {}
        self.__internalTriggeringPoints = {}
        self.__modeAccessPoints = {}
        self.__modeSwitchPoints = {}
        self.__parameterAccess = {}
        self.__readLocalVariables = {}
        self.__serverCallPoints = {}
        self.__waitPoints = {}
        self.__writtenLocalVariables = {}
        self.__variationPoint = None
        self.__serverCallPoints_childTypes = {'ASYNCHRONOUS-SERVER-CALL-POINT': 'AsynchronousServerCallPoint', 'SYNCHRONOUS-SERVER-CALL-POINT': 'SynchronousServerCallPoint', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__canBeInvokedConcurrently = self._read_scalar_element('CAN-BE-INVOKED-CONCURRENTLY', datatype_utils.get_bool_value)
        self.__symbol = self._read_scalar_element('SYMBOL', datatype_utils.get_string_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__arguments, '{*}ARGUMENTS/*', RunnableEntityArgument, file, 'arguments', refCounter)
        refCounter = self._build_child_collection(self.__asynchronousServerCallResultPoints, '{*}ASYNCHRONOUS-SERVER-CALL-RESULT-POINTS/*', AsynchronousServerCallResultPoint, file, 'asynchronousServerCallResultPoints', refCounter)
        refCounter = self._build_child_collection(self.__dataReadAccess, '{*}DATA-READ-ACCESSS/*', VariableAccess, file, 'dataReadAccess', refCounter)
        refCounter = self._build_child_collection(self.__dataReceivePointByArguments, '{*}DATA-RECEIVE-POINT-BY-ARGUMENTS/*', VariableAccess, file, 'dataReceivePointByArguments', refCounter)
        refCounter = self._build_child_collection(self.__dataReceivePointByValues, '{*}DATA-RECEIVE-POINT-BY-VALUES/*', VariableAccess, file, 'dataReceivePointByValues', refCounter)
        refCounter = self._build_child_collection(self.__dataSendPoints, '{*}DATA-SEND-POINTS/*', VariableAccess, file, 'dataSendPoints', refCounter)
        refCounter = self._build_child_collection(self.__dataWriteAccess, '{*}DATA-WRITE-ACCESSS/*', VariableAccess, file, 'dataWriteAccess', refCounter)
        refCounter = self._build_child_collection(self.__externalTriggeringPoints, '{*}EXTERNAL-TRIGGERING-POINTS/*', ExternalTriggeringPoint, file, 'externalTriggeringPoints', refCounter)
        refCounter = self._build_child_collection(self.__internalTriggeringPoints, '{*}INTERNAL-TRIGGERING-POINTS/*', InternalTriggeringPoint, file, 'internalTriggeringPoints', refCounter)
        refCounter = self._build_child_collection(self.__modeAccessPoints, '{*}MODE-ACCESS-POINTS/*', ModeAccessPoint, file, 'modeAccessPoints', refCounter)
        refCounter = self._build_child_collection(self.__modeSwitchPoints, '{*}MODE-SWITCH-POINTS/*', ModeSwitchPoint, file, 'modeSwitchPoints', refCounter)
        refCounter = self._build_child_collection(self.__parameterAccess, '{*}PARAMETER-ACCESSS/*', ParameterAccess, file, 'parameterAccess', refCounter)
        refCounter = self._build_child_collection(self.__readLocalVariables, '{*}READ-LOCAL-VARIABLES/*', VariableAccess, file, 'readLocalVariables', refCounter)
        refCounter = self._build_child_collection(self.__serverCallPoints, '{*}SERVER-CALL-POINTS/*', self.__serverCallPoints_childTypes, file, 'serverCallPoints', refCounter)
        refCounter = self._build_child_collection(self.__waitPoints, '{*}WAIT-POINTS/*', WaitPoint, file, 'waitPoints', refCounter)
        refCounter = self._build_child_collection(self.__writtenLocalVariables, '{*}WRITTEN-LOCAL-VARIABLES/*', VariableAccess, file, 'writtenLocalVariables', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_canBeInvokedConcurrently(self) -> bool:
        return self.__canBeInvokedConcurrently

    def set_canBeInvokedConcurrently(self, value: bool) -> None:
        self.__canBeInvokedConcurrently = value
        XDT.mark_attribute_dirty('canBeInvokedConcurrently', self)

    def get_symbol(self) -> str:
        return self.__symbol

    def set_symbol(self, value: str) -> None:
        self.__symbol = value
        XDT.mark_attribute_dirty('symbol', self)

    def get_arguments(self) -> list[RunnableEntityArgument]:
        return list(self.__arguments.keys())

    def __bind_argument(self, value: RunnableEntityArgument) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__arguments.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, RunnableEntityArgument) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RunnableEntityArgument or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'RunnableEntityArgument_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_argument_at_index(self, index: int, value: RunnableEntityArgument) -> None:
        """
        Adds a single value to the arguments at the given index
        """
        if value is not None:
            self.__bind_argument(value)
            AutosarNode._insert_at_index(self.__arguments, value, index)
            self._sync_add_to_merge_target(value)

    def add_argument(self, value: RunnableEntityArgument) -> None:
        """
        Adds a single value to the arguments
        """
        if value is not None:
            self.__bind_argument(value)
            self.__arguments[value] = None
            self._sync_add_to_merge_target(value)

    def set_arguments(self, values: list[RunnableEntityArgument]) -> None:
        """
        Adds a list of ref value to the arguments
        """
        for value in values:
            self.add_argument(value)

    def remove_argument(self, value: RunnableEntityArgument) -> None:
        """
        Removes a single value from arguments
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_arguments(self, values: list[RunnableEntityArgument]) -> None:
        """
        Removes a list of value from arguments
        """
        for value in values:
            self.remove_argument(value)

    def get_asynchronousServerCallResultPoints(self) -> list[AsynchronousServerCallResultPoint]:
        return list(self.__asynchronousServerCallResultPoints.keys())

    def __bind_asynchronousServerCallResultPoint(self, value: AsynchronousServerCallResultPoint) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__asynchronousServerCallResultPoints.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, AsynchronousServerCallResultPoint) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AsynchronousServerCallResultPoint or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'AsynchronousServerCallResultPoint_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['returnValueProvision', 'uuid', 'category', 'shortName', 'timestamp', 'checksum'])

