class RapidPrototypingScenario(ARElement):
    """
    This meta-class provides the ability to describe a Rapid Prototyping Scenario. Such a Rapid Prototyping Scenario consist out of two main aspects, the description of the byPassPoints and the relation to an rptHook.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RAPID-PROTOTYPING-SCENARIO'
        self._node = etree.Element('RAPID-PROTOTYPING-SCENARIO')
        self.__hostSystem = None
        self.__rptContainers = {}
        self.__rptProfiles = {}
        self.__rptSystem = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__rptContainers, '{*}RPT-CONTAINERS/*', RptContainer, file, 'rptContainers', refCounter)
        refCounter = self._build_child_collection(self.__rptProfiles, '{*}RPT-PROFILES/*', RptProfile, file, 'rptProfiles', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__hostSystem = self._resolve_single_reference('{*}HOST-SYSTEM-REF', self.__hostSystem)
        self.__rptSystem = self._resolve_single_reference('{*}RPT-SYSTEM-REF', self.__rptSystem)

    def get_hostSystem(self) -> System:
        return self.__hostSystem

    def set_hostSystem(self, value: System) -> None:
        """
        Adds a single value to the hostSystem
        """
        if value is not None:
            if isinstance(value, System) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of System or its sub-classes'.format(value))
            if self.__hostSystem is not None and self.__hostSystem.is_proxy() is False:
                self.__hostSystem.referenced_by.remove(self)
            self.__hostSystem = value
            value.referenced_by.add(self)
        elif self.__hostSystem is not None:
            if self.__hostSystem.is_proxy() is False:
                self.__hostSystem.referenced_by.remove(self)
            self.__hostSystem = None
        XDT.mark_dirty(self.__hostSystem, self)

    def get_rptContainers(self) -> list[RptContainer]:
        return list(self.__rptContainers.keys())

    def __bind_rptContainer(self, value: RptContainer) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__rptContainers.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, RptContainer) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RptContainer or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'RptContainer_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_rptContainer_at_index(self, index: int, value: RptContainer) -> None:
        """
        Adds a single value to the rptContainers at the given index
        """
        if value is not None:
            self.__bind_rptContainer(value)
            AutosarNode._insert_at_index(self.__rptContainers, value, index)
            self._sync_add_to_merge_target(value)

    def add_rptContainer(self, value: RptContainer) -> None:
        """
        Adds a single value to the rptContainers
        """
        if value is not None:
            self.__bind_rptContainer(value)
            self.__rptContainers[value] = None
            self._sync_add_to_merge_target(value)

    def set_rptContainers(self, values: list[RptContainer]) -> None:
        """
        Adds a list of ref value to the rptContainers
        """
        for value in values:
            self.add_rptContainer(value)

    def remove_rptContainer(self, value: RptContainer) -> None:
        """
        Removes a single value from rptContainers
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_rptContainers(self, values: list[RptContainer]) -> None:
        """
        Removes a list of value from rptContainers
        """
        for value in values:
            self.remove_rptContainer(value)

    def get_rptProfiles(self) -> list[RptProfile]:
        return list(self.__rptProfiles.keys())

    def __bind_rptProfile(self, value: RptProfile) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__rptProfiles.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, RptProfile) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RptProfile or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'RptProfile_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_rptProfile_at_index(self, index: int, value: RptProfile) -> None:
        """
        Adds a single value to the rptProfiles at the given index
        """
        if value is not None:
            self.__bind_rptProfile(value)
            AutosarNode._insert_at_index(self.__rptProfiles, value, index)
            self._sync_add_to_merge_target(value)

    def add_rptProfile(self, value: RptProfile) -> None:
        """
        Adds a single value to the rptProfiles
        """
        if value is not None:
            self.__bind_rptProfile(value)
            self.__rptProfiles[value] = None
            self._sync_add_to_merge_target(value)

    def set_rptProfiles(self, values: list[RptProfile]) -> None:
        """
        Adds a list of ref value to the rptProfiles
        """
        for value in values:
            self.add_rptProfile(value)

    def remove_rptProfile(self, value: RptProfile) -> None:
        """
        Removes a single value from rptProfiles
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_rptProfiles(self, values: list[RptProfile]) -> None:
        """
        Removes a list of value from rptProfiles
        """
        for value in values:
            self.remove_rptProfile(value)

    def get_rptSystem(self) -> System:
        return self.__rptSystem

    def set_rptSystem(self, value: System) -> None:
        """
        Adds a single value to the rptSystem
        """
        if value is not None:
            if isinstance(value, System) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of System or its sub-classes'.format(value))
            if self.__rptSystem is not None and self.__rptSystem.is_proxy() is False:
                self.__rptSystem.referenced_by.remove(self)
            self.__rptSystem = value
            value.referenced_by.add(self)
        elif self.__rptSystem is not None:
            if self.__rptSystem.is_proxy() is False:
                self.__rptSystem.referenced_by.remove(self)
            self.__rptSystem = None
        XDT.mark_dirty(self.__rptSystem, self)

    def new_RptProfile(self, name: str=None) -> RptProfile:
        """
        Creates a new RptProfile under the RapidPrototypingScenario.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        RptProfile_obj = RptProfile()
        if isinstance(RptProfile_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        RptProfile_obj.name = name if isinstance(RptProfile_obj, Referrable) else None
        self.add_rptProfile(RptProfile_obj)
        if isinstance(RptProfile_obj, Referrable):
            RptProfile_obj.set_shortName(name)
        return RptProfile_obj

    def new_RptContainer(self, name: str=None) -> RptContainer:
        """
        Creates a new RptContainer under the RapidPrototypingScenario.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        RptContainer_obj = RptContainer()
        if isinstance(RptContainer_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        RptContainer_obj.name = name if isinstance(RptContainer_obj, Referrable) else None
        self.add_rptContainer(RptContainer_obj)
        if isinstance(RptContainer_obj, Referrable):
            RptContainer_obj.set_shortName(name)
        return RptContainer_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__rptContainers)
        children.extend(self.__rptProfiles)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__rptContainers:
            return 'rptContainers'
        if child in self.__rptProfiles:
            return 'rptProfiles'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'rptContainers':
            self.__rptContainers[child] = None
        elif containment_slot == 'rptProfiles':
            self.__rptProfiles[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'rptContainers':
            self.__rptContainers.pop(child, None)
        elif containment_slot == 'rptProfiles':
            self.__rptProfiles.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['HostSystem'] = self.__hostSystem
        property_values['RptSystem'] = self.__rptSystem
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of RapidPrototypingScenario node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARElement()
        self._save_single_reference('HOST-SYSTEM-REF', self.__hostSystem, self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_child_collection('RPT-CONTAINERS', None, self.__rptContainers, self._insert_after_tags + ['HOST-SYSTEM-REF', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_child_collection('RPT-PROFILES', None, self.__rptProfiles, self._insert_after_tags + ['RPT-CONTAINERS', 'HOST-SYSTEM-REF', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('RPT-SYSTEM-REF', self.__rptSystem, self._insert_after_tags + ['RPT-PROFILES', 'RPT-CONTAINERS', 'HOST-SYSTEM-REF', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

