        refCounter = self._build_child_collection(self.__rptContainers, '{*}RPT-CONTAINERS/*', RptContainer, file, 'rptContainers', refCounter)
        self.__rptExecutableEntityProperties = self._build_single_child('{*}RPT-EXECUTABLE-ENTITY-PROPERTIES', RptExecutableEntityProperties, file, 'rptExecutableEntityProperties')
        refCounter = self._build_child_collection(self.__rptHooks, '{*}RPT-HOOKS/*', RptHook, file, 'rptHooks', refCounter)
        self.__rptImplPolicy = self._build_single_child('{*}RPT-IMPL-POLICY', RptImplPolicy, file, 'rptImplPolicy')
        self.__rptSwPrototypingAccess = self._build_single_child('{*}RPT-SW-PROTOTYPING-ACCESS', RptSwPrototypingAccess, file, 'rptSwPrototypingAccess')
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
