class EcucChoiceReferenceDef(EcucAbstractInternalReferenceDef):
    """
    Specify alternative references where in the ECU Configuration description only one of the specified references will actually be used.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ECUC-CHOICE-REFERENCE-DEF'
        self._node = etree.Element('ECUC-CHOICE-REFERENCE-DEF')
        self.__destinations = {}


    def _resolve_references(self):
        super()._resolve_references()
        self.__destinations = self._resolve_reference_list('{*}DESTINATION-REFS/*', self.__destinations)

    def get_destinations(self) -> list[EcucContainerDef]:
        return list(self.__destinations.keys())

    def __bind_destination(self, value: EcucContainerDef) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__destinations.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, EcucContainerDef) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcucContainerDef or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_destination(self, value: EcucContainerDef) -> None:
        """
        Adds a single value to the destinations
        """
        if value is not None:
            self.__bind_destination(value)
            self.__destinations[value] = None

    def set_destinations(self, values: list[EcucContainerDef]) -> None:
        """
        Adds a list of ref value to the destinations
        """
        for value in values:
            self.add_destination(value)

    def remove_destination(self, value: EcucContainerDef) -> None:
        """
        Removes a single value from destinations
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__destinations.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_destinations(self, values: list[EcucContainerDef]) -> None:
        """
        Removes a list of value from destinations
        """
        for value in values:
            self.remove_destination(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Destinations'] = self.__destinations
        return property_values

