class EcucModuleDef(ARElement,AtpBlueprint,AtpBlueprintable,EcucDefinitionElement):
    """
    Used as the top-level element for configuration definition for Software Modules, including BSW and RTE as well as ECU Infrastructure.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ECUC-MODULE-DEF'
        self._node = etree.Element('ECUC-MODULE-DEF')
        self.__apiServicePrefix = None
        self.__postBuildVariantSupport = None
        self.__supportedConfigVariants = None
        self.__refinedModuleDef = None
        self.__containers = {}
        self.__containers_childTypes = {'ECUC-CHOICE-CONTAINER-DEF': 'EcucChoiceContainerDef', 'ECUC-PARAM-CONF-CONTAINER-DEF': 'EcucParamConfContainerDef', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__apiServicePrefix = self._read_scalar_element('API-SERVICE-PREFIX', datatype_utils.get_string_value)
        self.__postBuildVariantSupport = self._read_scalar_element('POST-BUILD-VARIANT-SUPPORT', datatype_utils.get_bool_value)
        self.__supportedConfigVariants = self._read_own_text(EcucConfigurationVariantEnum.get)

        refCounter = 0
        refCounter = self._build_child_collection(self.__containers, '{*}CONTAINERS/*', self.__containers_childTypes, file, 'containers', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__refinedModuleDef = self._resolve_single_reference('{*}REFINED-MODULE-DEF-REF', self.__refinedModuleDef)

    def get_apiServicePrefix(self) -> str:
        return self.__apiServicePrefix

    def set_apiServicePrefix(self, value: str) -> None:
        self.__apiServicePrefix = value
        XDT.mark_attribute_dirty('apiServicePrefix', self)

    def get_postBuildVariantSupport(self) -> bool:
        return self.__postBuildVariantSupport

    def set_postBuildVariantSupport(self, value: bool) -> None:
        self.__postBuildVariantSupport = value
        XDT.mark_attribute_dirty('postBuildVariantSupport', self)

    def get_supportedConfigVariants(self) -> EcucConfigurationVariantEnum:
        return self.__supportedConfigVariants

    def set_supportedConfigVariants(self, value: EcucConfigurationVariantEnum) -> None:
        self.__supportedConfigVariants = value
        XDT.mark_attribute_dirty('supportedConfigVariants', self)

    def get_refinedModuleDef(self) -> EcucModuleDef:
        return self.__refinedModuleDef

    def set_refinedModuleDef(self, value: EcucModuleDef) -> None:
        """
        Adds a single value to the refinedModuleDef
        """
        if value is not None:
            if isinstance(value, EcucModuleDef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcucModuleDef or its sub-classes'.format(value))
            if self.__refinedModuleDef is not None and self.__refinedModuleDef.is_proxy() is False:
                self.__refinedModuleDef.referenced_by.remove(self)
            self.__refinedModuleDef = value
            value.referenced_by.add(self)
        elif self.__refinedModuleDef is not None:
            if self.__refinedModuleDef.is_proxy() is False:
                self.__refinedModuleDef.referenced_by.remove(self)
            self.__refinedModuleDef = None
        XDT.mark_dirty(self.__refinedModuleDef, self)

    def get_containers(self) -> list[EcucContainerDef]:
        return list(self.__containers.keys())

