class BswVariableAccess(Referrable):
    """
    The presence of a BswVariableAccess implies that a BswModuleEntity needs access to a VariableDataPrototype via the BSW Scheduler., , The kind of access is specified by the role in which the class is used.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-VARIABLE-ACCESS'
        self._node = etree.Element('BSW-VARIABLE-ACCESS')
        self.__accessedVariable = None
        self.__contextLimitations = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__accessedVariable = self._resolve_single_reference('{*}ACCESSED-VARIABLE-REF', self.__accessedVariable)
        self.__contextLimitations = self._resolve_reference_list('{*}CONTEXT-LIMITATION-REFS/*', self.__contextLimitations)

    def get_accessedVariable(self) -> VariableDataPrototype:
        return self.__accessedVariable

    def set_accessedVariable(self, value: VariableDataPrototype) -> None:
        """
        Adds a single value to the accessedVariable
        """
        if value is not None:
            if isinstance(value, VariableDataPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariableDataPrototype or its sub-classes'.format(value))
            if self.__accessedVariable is not None and self.__accessedVariable.is_proxy() is False:
                self.__accessedVariable.referenced_by.remove(self)
            self.__accessedVariable = value
            value.referenced_by.add(self)
        elif self.__accessedVariable is not None:
            if self.__accessedVariable.is_proxy() is False:
                self.__accessedVariable.referenced_by.remove(self)
            self.__accessedVariable = None
        XDT.mark_dirty(self.__accessedVariable, self)

    def get_contextLimitations(self) -> list[BswDistinguishedPartition]:
        return list(self.__contextLimitations.keys())

    def __bind_contextLimitation(self, value: BswDistinguishedPartition) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__contextLimitations.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, BswDistinguishedPartition) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BswDistinguishedPartition or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_contextLimitation(self, value: BswDistinguishedPartition) -> None:
        """
        Adds a single value to the contextLimitations
        """
        if value is not None:
            self.__bind_contextLimitation(value)
            self.__contextLimitations[value] = None

    def set_contextLimitations(self, values: list[BswDistinguishedPartition]) -> None:
        """
        Adds a list of ref value to the contextLimitations
        """
        for value in values:
            self.add_contextLimitation(value)

    def remove_contextLimitation(self, value: BswDistinguishedPartition) -> None:
        """
        Removes a single value from contextLimitations
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__contextLimitations.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_contextLimitations(self, values: list[BswDistinguishedPartition]) -> None:
        """
        Removes a list of value from contextLimitations
        """
        for value in values:
            self.remove_contextLimitation(value)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the BswVariableAccess.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

