        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__containerIPduHeaderByteOrder = self._read_scalar_element('CONTAINER-I-PDU-HEADER-BYTE-ORDER', ByteOrderEnum.get)
        self.__ecuExtractVersion = self._read_scalar_element('ECU-EXTRACT-VERSION', datatype_utils.get_string_value)
