class RootSwCompositionPrototype(AtpPrototype):
    """
    The RootSwCompositionPrototype represents the top-level-composition of software components within a given System., , @RESTRICT_TO_STANDARD:CP:AP!, According to the use case of the System, this may for example be a more or less complete VFB description, the software of a System Extract or the software of a flat ECU Extract with only atomic SWCs. , @RESTRICT_TO_STANDARD:FO!, This may for example be a more or less complete VFB++ description., @END_RESTRICT_TO_STANDARD!, , Therefore the RootSwComposition will only occasionally contain all atomic software components that are used in a complete VFB System. The OEM is primarily interested in the required functionality and the interfaces defining the integration of the Software Component into the System. The internal structure of such a component contains often substantial intellectual property of a supplier. Therefore a top-level software composition will often contain empty compositions which represent subsystems. , , @RESTRICT_TO_STANDARD:CP:AP!, The contained SwComponentPrototypes are fully specified by their SwComponentTypes (including PortPrototypes, PortInterfaces, VariableDataPrototypes, SwcInternalBehavior etc.), and their ports are interconnected using SwConnectorPrototypes., @RESTRICT_TO_STANDARD:FO!, The contained SwComponentPrototypes are fully specified by their SwComponentTypes (including PortPrototypes, PortInterfaces, VariableDataPrototypes, etc.)., @END_RESTRICT_TO_STANDARD!
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ROOT-SW-COMPOSITION-PROTOTYPE'
        self._node = etree.Element('ROOT-SW-COMPOSITION-PROTOTYPE')
        self.__calibrationParameterValueSets = {}
        self.__flatMap = None
        self.__softwareComposition = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__calibrationParameterValueSets = self._resolve_reference_list('{*}CALIBRATION-PARAMETER-VALUE-SET-REFS/*', self.__calibrationParameterValueSets)
        self.__flatMap = self._resolve_single_reference('{*}FLAT-MAP-REF', self.__flatMap)
        self.__softwareComposition = self._resolve_single_reference('{*}SOFTWARE-COMPOSITION-TREF', self.__softwareComposition)

    def get_calibrationParameterValueSets(self) -> list[CalibrationParameterValueSet]:
        return list(self.__calibrationParameterValueSets.keys())

    def __bind_calibrationParameterValueSet(self, value: CalibrationParameterValueSet) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__calibrationParameterValueSets.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, CalibrationParameterValueSet) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CalibrationParameterValueSet or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_calibrationParameterValueSet(self, value: CalibrationParameterValueSet) -> None:
        """
        Adds a single value to the calibrationParameterValueSets
        """
        if value is not None:
            self.__bind_calibrationParameterValueSet(value)
            self.__calibrationParameterValueSets[value] = None

    def set_calibrationParameterValueSets(self, values: list[CalibrationParameterValueSet]) -> None:
        """
        Adds a list of ref value to the calibrationParameterValueSets
        """
        for value in values:
            self.add_calibrationParameterValueSet(value)

    def remove_calibrationParameterValueSet(self, value: CalibrationParameterValueSet) -> None:
        """
        Removes a single value from calibrationParameterValueSets
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__calibrationParameterValueSets.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_calibrationParameterValueSets(self, values: list[CalibrationParameterValueSet]) -> None:
        """
        Removes a list of value from calibrationParameterValueSets
        """
        for value in values:
            self.remove_calibrationParameterValueSet(value)

    def get_flatMap(self) -> FlatMap:
        return self.__flatMap

    def set_flatMap(self, value: FlatMap) -> None:
        """
        Adds a single value to the flatMap
        """
        if value is not None:
            if isinstance(value, FlatMap) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FlatMap or its sub-classes'.format(value))
            if self.__flatMap is not None and self.__flatMap.is_proxy() is False:
                self.__flatMap.referenced_by.remove(self)
            self.__flatMap = value
            value.referenced_by.add(self)
        elif self.__flatMap is not None:
            if self.__flatMap.is_proxy() is False:
                self.__flatMap.referenced_by.remove(self)
            self.__flatMap = None
        XDT.mark_dirty(self.__flatMap, self)

    def get_softwareComposition(self) -> CompositionSwComponentType:
        return self.__softwareComposition

    def set_softwareComposition(self, value: CompositionSwComponentType) -> None:
        """
        Adds a single value to the softwareComposition
        """
        if value is not None:
            if isinstance(value, CompositionSwComponentType) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CompositionSwComponentType or its sub-classes'.format(value))
            if self.__softwareComposition is not None and self.__softwareComposition.is_proxy() is False:
                self.__softwareComposition.referenced_by.remove(self)
            self.__softwareComposition = value
            value.referenced_by.add(self)
        elif self.__softwareComposition is not None:
            if self.__softwareComposition.is_proxy() is False:
                self.__softwareComposition.referenced_by.remove(self)
            self.__softwareComposition = None
        XDT.mark_dirty(self.__softwareComposition, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the RootSwCompositionPrototype.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['CalibrationParameterValueSets'] = self.__calibrationParameterValueSets
        property_values['FlatMap'] = self.__flatMap
        property_values['SoftwareComposition'] = self.__softwareComposition
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of RootSwCompositionPrototype node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_AtpPrototype()
        self._save_reference_list('CALIBRATION-PARAMETER-VALUE-SET-REFS', 'CALIBRATION-PARAMETER-VALUE-SET-REF', self.__calibrationParameterValueSets, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('FLAT-MAP-REF', self.__flatMap, self._insert_after_tags + ['CALIBRATION-PARAMETER-VALUE-SET-REFS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('SOFTWARE-COMPOSITION-TREF', self.__softwareComposition, self._insert_after_tags + ['FLAT-MAP-REF', 'CALIBRATION-PARAMETER-VALUE-SET-REFS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['SOFTWARE-COMPOSITION-TREF', 'FLAT-MAP-REF', 'CALIBRATION-PARAMETER-VALUE-SET-REFS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

