class MacSecParticipantSet(UploadableDesignElement):
    """
    Collection of MACsec Kay Participants on an Ethernet Link.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MAC-SEC-PARTICIPANT-SET'
        self._node = etree.Element('MAC-SEC-PARTICIPANT-SET')
        self.__ethernetCluster = None
        self.__mkaParticipants = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__mkaParticipants, '{*}MKA-PARTICIPANTS/*', MacSecKayParticipant, file, 'mkaParticipants', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__ethernetCluster = self._resolve_single_reference('{*}ETHERNET-CLUSTER-REF', self.__ethernetCluster)

    def get_ethernetCluster(self) -> EthernetCluster:
        return self.__ethernetCluster

    def set_ethernetCluster(self, value: EthernetCluster) -> None:
        """
        Adds a single value to the ethernetCluster
        """
        if value is not None:
            if isinstance(value, EthernetCluster) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EthernetCluster or its sub-classes'.format(value))
            if self.__ethernetCluster is not None and self.__ethernetCluster.is_proxy() is False:
                self.__ethernetCluster.referenced_by.remove(self)
            self.__ethernetCluster = value
            value.referenced_by.add(self)
        elif self.__ethernetCluster is not None:
            if self.__ethernetCluster.is_proxy() is False:
                self.__ethernetCluster.referenced_by.remove(self)
            self.__ethernetCluster = None
        XDT.mark_dirty(self.__ethernetCluster, self)

    def get_mkaParticipants(self) -> list[MacSecKayParticipant]:
        return list(self.__mkaParticipants.keys())

    def __bind_mkaParticipant(self, value: MacSecKayParticipant) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__mkaParticipants.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, MacSecKayParticipant) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MacSecKayParticipant or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'MacSecKayParticipant_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_mkaParticipant_at_index(self, index: int, value: MacSecKayParticipant) -> None:
        """
        Adds a single value to the mkaParticipants at the given index
        """
        if value is not None:
            self.__bind_mkaParticipant(value)
            AutosarNode._insert_at_index(self.__mkaParticipants, value, index)
            self._sync_add_to_merge_target(value)

    def add_mkaParticipant(self, value: MacSecKayParticipant) -> None:
        """
        Adds a single value to the mkaParticipants
        """
        if value is not None:
            self.__bind_mkaParticipant(value)
            self.__mkaParticipants[value] = None
            self._sync_add_to_merge_target(value)

    def set_mkaParticipants(self, values: list[MacSecKayParticipant]) -> None:
        """
        Adds a list of ref value to the mkaParticipants
        """
        for value in values:
            self.add_mkaParticipant(value)

    def remove_mkaParticipant(self, value: MacSecKayParticipant) -> None:
        """
        Removes a single value from mkaParticipants
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_mkaParticipants(self, values: list[MacSecKayParticipant]) -> None:
        """
        Removes a list of value from mkaParticipants
        """
        for value in values:
            self.remove_mkaParticipant(value)

    def new_MkaParticipant(self, name: str=None) -> MacSecKayParticipant:
        """
        Creates a new MacSecKayParticipant under the MacSecParticipantSet.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        MacSecKayParticipant_obj = MacSecKayParticipant()
        if isinstance(MacSecKayParticipant_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        MacSecKayParticipant_obj.name = name if isinstance(MacSecKayParticipant_obj, Referrable) else None
        self.add_mkaParticipant(MacSecKayParticipant_obj)
        if isinstance(MacSecKayParticipant_obj, Referrable):
            MacSecKayParticipant_obj.set_shortName(name)
        return MacSecKayParticipant_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__mkaParticipants)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__mkaParticipants:
            return 'mkaParticipants'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'mkaParticipants':
            self.__mkaParticipants[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'mkaParticipants':
            self.__mkaParticipants.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['EthernetCluster'] = self.__ethernetCluster
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of MacSecParticipantSet node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_UploadableDesignElement()
        self._save_single_reference('ETHERNET-CLUSTER-REF', self.__ethernetCluster, self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_child_collection('MKA-PARTICIPANTS', None, self.__mkaParticipants, self._insert_after_tags + ['ETHERNET-CLUSTER-REF', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

