class SocketConnectionBundle(Referrable):
    """
    This elements groups SocketConnections, i.e. specifies socket connections belonging to the bundle and describes properties which are common for all socket connections in the bundle.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SOCKET-CONNECTION-BUNDLE'
        self._node = etree.Element('SOCKET-CONNECTION-BUNDLE')
        self.__differentiatedServiceField = None
        self.__flowLabel = None
        self.__pathMtuDiscoveryEnabled = None
        self.__udpChecksumHandling = None
        self.__bundledConnections = {}
        self.__pdus = {}
        self.__serverPort = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__differentiatedServiceField = self._read_scalar_element('DIFFERENTIATED-SERVICE-FIELD', datatype_utils.get_int_value)
        self.__flowLabel = self._read_scalar_element('FLOW-LABEL', datatype_utils.get_int_value)
        self.__pathMtuDiscoveryEnabled = self._read_scalar_element('PATH-MTU-DISCOVERY-ENABLED', datatype_utils.get_bool_value)
        self.__udpChecksumHandling = self._read_scalar_element('UDP-CHECKSUM-HANDLING', UdpChecksumCalculationEnum.get)

        refCounter = 0
        refCounter = self._build_child_collection(self.__bundledConnections, '{*}BUNDLED-CONNECTIONS/*', SocketConnection, file, 'bundledConnections', refCounter)
        refCounter = self._build_child_collection(self.__pdus, '{*}PDUS/*', SocketConnectionIpduIdentifier, file, 'pdus', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__serverPort = self._resolve_single_reference('{*}SERVER-PORT-REF', self.__serverPort)

