        refCounter = self._build_child_collection(self.__remoteAddress, '{*}REMOTE-ADDRESSS/*', SocketAddressRefConditional, file, 'remoteAddress', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
