        """
        Adds a single value to the canTpChannel
        """
        if value is not None:
            if isinstance(value, CanTpChannel) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CanTpChannel or its sub-classes'.format(value))
            if self.__canTpChannel is not None and self.__canTpChannel.is_proxy() is False:
                self.__canTpChannel.referenced_by.remove(self)
            self.__canTpChannel = value
            value.referenced_by.add(self)
        elif self.__canTpChannel is not None:
            if self.__canTpChannel.is_proxy() is False:
                self.__canTpChannel.referenced_by.remove(self)
