class EthTpConfig(TpConfig):
    """
    This element defines which PduTriggerings shall be handled using "TP" semantics.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ETH-TP-CONFIG'
        self._node = etree.Element('ETH-TP-CONFIG')
        self.__tpConnections = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
