class J1939TpPg(ARObject):
    """
    A J1939TpPg represents one J1939 message (parameter group, PG) identified by the PGN (parameter group number) that can be received or transmitted via J1939Tp.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'J-1939-TP-PG'
        self._node = etree.Element('J-1939-TP-PG')
        self.__pgn = None
        self.__requestable = None
        self.__directPdu = None
        self.__sdus = {}
        self.__tpSdu = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__pgn = self._read_scalar_element('PGN', datatype_utils.get_int_value)
        self.__requestable = self._read_scalar_element('REQUESTABLE', datatype_utils.get_bool_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__directPdu = self._resolve_single_reference('{*}DIRECT-PDU-REF', self.__directPdu)
        self.__sdus = self._resolve_reference_list('{*}SDU-REFS/*', self.__sdus)
        self.__tpSdu = self._resolve_single_reference('{*}TP-SDU-REF', self.__tpSdu)

    def get_pgn(self) -> int:
        return self.__pgn

    def set_pgn(self, value: int) -> None:
        self.__pgn = value
        XDT.mark_attribute_dirty('pgn', self)

    def get_requestable(self) -> bool:
        return self.__requestable

    def set_requestable(self, value: bool) -> None:
        self.__requestable = value
        XDT.mark_attribute_dirty('requestable', self)

    def get_directPdu(self) -> NPdu:
        return self.__directPdu

    def set_directPdu(self, value: NPdu) -> None:
        """
        Adds a single value to the directPdu
        """
        if value is not None:
            if isinstance(value, NPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NPdu or its sub-classes'.format(value))
            if self.__directPdu is not None and self.__directPdu.is_proxy() is False:
                self.__directPdu.referenced_by.remove(self)
            self.__directPdu = value
            value.referenced_by.add(self)
        elif self.__directPdu is not None:
            if self.__directPdu.is_proxy() is False:
                self.__directPdu.referenced_by.remove(self)
            self.__directPdu = None
        XDT.mark_dirty(self.__directPdu, self)

    def get_sdus(self) -> list[IPdu]:
        return list(self.__sdus.keys())

    def __bind_sdu(self, value: IPdu) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__sdus.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, IPdu) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IPdu or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_sdu(self, value: IPdu) -> None:
        """
        Adds a single value to the sdus
        """
        if value is not None:
            self.__bind_sdu(value)
            self.__sdus[value] = None

    def set_sdus(self, values: list[IPdu]) -> None:
        """
        Adds a list of ref value to the sdus
        """
        for value in values:
            self.add_sdu(value)

    def remove_sdu(self, value: IPdu) -> None:
        """
        Removes a single value from sdus
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__sdus.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_sdus(self, values: list[IPdu]) -> None:
        """
        Removes a list of value from sdus
        """
        for value in values:
            self.remove_sdu(value)

    def get_tpSdu(self) -> IPdu:
        return self.__tpSdu

    def set_tpSdu(self, value: IPdu) -> None:
        """
        Adds a single value to the tpSdu
        """
        if value is not None:
            if isinstance(value, IPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IPdu or its sub-classes'.format(value))
            if self.__tpSdu is not None and self.__tpSdu.is_proxy() is False:
                self.__tpSdu.referenced_by.remove(self)
            self.__tpSdu = value
            value.referenced_by.add(self)
        elif self.__tpSdu is not None:
            if self.__tpSdu.is_proxy() is False:
                self.__tpSdu.referenced_by.remove(self)
            self.__tpSdu = None
        XDT.mark_dirty(self.__tpSdu, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Pgn'] = self.__pgn
        property_values['Requestable'] = self.__requestable
        property_values['DirectPdu'] = self.__directPdu
        property_values['Sdus'] = self.__sdus
        property_values['TpSdu'] = self.__tpSdu
        return property_values


    def _save_contents(self):
        """
        Saves the content of J1939TpPg node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_single_reference('DIRECT-PDU-REF', self.__directPdu, self._insert_after_tags + ['T', 'S'])
        self._save_scalar_element('PGN', 'pgn', str(self.__pgn) if self.__pgn is not None else None, create_after_nodes = ['DIRECT-PDU-REF', 'T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('REQUESTABLE', 'requestable', ('true' if self.__requestable is True else 'false') if self.__requestable is not None else None, create_after_nodes = ['PGN', 'DIRECT-PDU-REF', 'T', 'S'] + self._insert_after_tags)
        self._save_reference_list('SDU-REFS', 'SDU-REF', self.__sdus, self._insert_after_tags + ['REQUESTABLE', 'PGN', 'DIRECT-PDU-REF', 'T', 'S'])
        self._save_single_reference('TP-SDU-REF', self.__tpSdu, self._insert_after_tags + ['SDU-REFS', 'REQUESTABLE', 'PGN', 'DIRECT-PDU-REF', 'T', 'S'])

class J1939TpNode(Identifiable):
    """
    TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'J-1939-TP-NODE'
        self._node = etree.Element('J-1939-TP-NODE')
        self.__connector = None
        self.__tpAddress = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__connector = self._resolve_single_reference('{*}CONNECTOR-REF', self.__connector)
        self.__tpAddress = self._resolve_single_reference('{*}TP-ADDRESS-REF', self.__tpAddress)

    def get_connector(self) -> CommunicationConnector:
        return self.__connector

    def set_connector(self, value: CommunicationConnector) -> None:
        """
        Adds a single value to the connector
        """
        if value is not None:
            if isinstance(value, CommunicationConnector) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CommunicationConnector or its sub-classes'.format(value))
            if self.__connector is not None and self.__connector.is_proxy() is False:
                self.__connector.referenced_by.remove(self)
            self.__connector = value
            value.referenced_by.add(self)
        elif self.__connector is not None:
            if self.__connector.is_proxy() is False:
                self.__connector.referenced_by.remove(self)
            self.__connector = None
        XDT.mark_dirty(self.__connector, self)

    def get_tpAddress(self) -> TpAddress:
        return self.__tpAddress

    def set_tpAddress(self, value: TpAddress) -> None:
        """
        Adds a single value to the tpAddress
        """
        if value is not None:
            if isinstance(value, TpAddress) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TpAddress or its sub-classes'.format(value))
            if self.__tpAddress is not None and self.__tpAddress.is_proxy() is False:
                self.__tpAddress.referenced_by.remove(self)
            self.__tpAddress = value
            value.referenced_by.add(self)
        elif self.__tpAddress is not None:
            if self.__tpAddress.is_proxy() is False:
                self.__tpAddress.referenced_by.remove(self)
            self.__tpAddress = None
        XDT.mark_dirty(self.__tpAddress, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the J1939TpNode.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Connector'] = self.__connector
        property_values['TpAddress'] = self.__tpAddress
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of J1939TpNode node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        self._save_single_reference('CONNECTOR-REF', self.__connector, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('TP-ADDRESS-REF', self.__tpAddress, self._insert_after_tags + ['CONNECTOR-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['TP-ADDRESS-REF', 'CONNECTOR-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

class LinTpConfig(TpConfig):
    """
    This element defines exactly one Lin TP Configuration. , , One LinTpConfig element shall be created for each Lin Network in the System.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'LIN-TP-CONFIG'
        self._node = etree.Element('LIN-TP-CONFIG')
        self.__tpAddress = {}
        self.__tpConnections = {}
        self.__tpNodes = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__tpAddress, '{*}TP-ADDRESSS/*', TpAddress, file, 'tpAddress', refCounter)
        refCounter = self._build_child_collection(self.__tpConnections, '{*}TP-CONNECTIONS/*', LinTpConnection, file, 'tpConnections', refCounter)
        refCounter = self._build_child_collection(self.__tpNodes, '{*}TP-NODES/*', LinTpNode, file, 'tpNodes', refCounter)
        return self

    def get_tpAddress(self) -> list[TpAddress]:
        return list(self.__tpAddress.keys())

    def __bind_tpAddres(self, value: TpAddress) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tpAddress.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, TpAddress) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TpAddress or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'TpAddress_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_tpAddres_at_index(self, index: int, value: TpAddress) -> None:
        """
        Adds a single value to the tpAddress at the given index
        """
        if value is not None:
            self.__bind_tpAddres(value)
            AutosarNode._insert_at_index(self.__tpAddress, value, index)
            self._sync_add_to_merge_target(value)

    def add_tpAddres(self, value: TpAddress) -> None:
        """
        Adds a single value to the tpAddress
        """
        if value is not None:
            self.__bind_tpAddres(value)
            self.__tpAddress[value] = None
            self._sync_add_to_merge_target(value)

    def set_tpAddress(self, values: list[TpAddress]) -> None:
        """
        Adds a list of ref value to the tpAddress
        """
        for value in values:
            self.add_tpAddres(value)

    def remove_tpAddres(self, value: TpAddress) -> None:
        """
        Removes a single value from tpAddress
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

