class GlobalTimeGateway(Identifiable):
    """
    This represents the ability to define a time gateway for establishing a global time domain over several communication clusters.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'GLOBAL-TIME-GATEWAY'
        self._node = etree.Element('GLOBAL-TIME-GATEWAY')
        self.__host = None
        self.__master = None
        self.__slave = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__host = self._resolve_single_reference('{*}HOST-REF', self.__host)
        self.__master = self._resolve_single_reference('{*}MASTER-REF', self.__master)
        self.__slave = self._resolve_single_reference('{*}SLAVE-REF', self.__slave)

    def get_host(self) -> EcuInstance:
        return self.__host

    def set_host(self, value: EcuInstance) -> None:
        """
        Adds a single value to the host
        """
        if value is not None:
            if isinstance(value, EcuInstance) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcuInstance or its sub-classes'.format(value))
            if self.__host is not None and self.__host.is_proxy() is False:
                self.__host.referenced_by.remove(self)
            self.__host = value
            value.referenced_by.add(self)
        elif self.__host is not None:
            if self.__host.is_proxy() is False:
                self.__host.referenced_by.remove(self)
            self.__host = None
        XDT.mark_dirty(self.__host, self)

    def get_master(self) -> GlobalTimeMaster:
        return self.__master

    def set_master(self, value: GlobalTimeMaster) -> None:
        """
        Adds a single value to the master
        """
        if value is not None:
            if isinstance(value, GlobalTimeMaster) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of GlobalTimeMaster or its sub-classes'.format(value))
            if self.__master is not None and self.__master.is_proxy() is False:
                self.__master.referenced_by.remove(self)
            self.__master = value
            value.referenced_by.add(self)
        elif self.__master is not None:
            if self.__master.is_proxy() is False:
                self.__master.referenced_by.remove(self)
            self.__master = None
        XDT.mark_dirty(self.__master, self)

    def get_slave(self) -> GlobalTimeSlave:
        return self.__slave

    def set_slave(self, value: GlobalTimeSlave) -> None:
        """
        Adds a single value to the slave
        """
        if value is not None:
            if isinstance(value, GlobalTimeSlave) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of GlobalTimeSlave or its sub-classes'.format(value))
            if self.__slave is not None and self.__slave.is_proxy() is False:
                self.__slave.referenced_by.remove(self)
            self.__slave = value
            value.referenced_by.add(self)
        elif self.__slave is not None:
            if self.__slave.is_proxy() is False:
                self.__slave.referenced_by.remove(self)
            self.__slave = None
        XDT.mark_dirty(self.__slave, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the GlobalTimeGateway.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Host'] = self.__host
        property_values['Master'] = self.__master
        property_values['Slave'] = self.__slave
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of GlobalTimeGateway node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        self._save_single_reference('HOST-REF', self.__host, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('MASTER-REF', self.__master, self._insert_after_tags + ['HOST-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('SLAVE-REF', self.__slave, self._insert_after_tags + ['MASTER-REF', 'HOST-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['SLAVE-REF', 'MASTER-REF', 'HOST-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

class NetworkSegmentIdentification(ARObject):
    """
    This meta-class represents the ability to identify the PhysicalChannel on a system scope in a numerical way. One possible application of this approach is the Time Validation.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'NETWORK-SEGMENT-IDENTIFICATION'
        self._node = etree.Element('NETWORK-SEGMENT-IDENTIFICATION')
        self.__networkSegmentId = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__networkSegmentId = self._read_scalar_element('NETWORK-SEGMENT-ID', datatype_utils.get_int_value)

        return self

    def get_networkSegmentId(self) -> int:
        return self.__networkSegmentId

    def set_networkSegmentId(self, value: int) -> None:
        self.__networkSegmentId = value
        XDT.mark_attribute_dirty('networkSegmentId', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['NetworkSegmentId'] = self.__networkSegmentId
        return property_values


    def _save_contents(self):
        """
        Saves the content of NetworkSegmentIdentification node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_scalar_element('NETWORK-SEGMENT-ID', 'networkSegmentId', str(self.__networkSegmentId) if self.__networkSegmentId is not None else None, create_after_nodes = ['T', 'S'] + self._insert_after_tags)

class GlobalTimeDomainRefConditional(ARObject):
    """
    This element was generated/modified due to an atpVariation stereotype.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'GLOBAL-TIME-DOMAIN-REF-CONDITIONAL'
        self._node = etree.Element('GLOBAL-TIME-DOMAIN-REF-CONDITIONAL')
        self.__globalTimeDomain = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

