class ApplicationPartitionToEcuPartitionMapping(Identifiable):
    """
    Maps ApplicationPartitions to EcuPartitions. With this mapping an OEM has the option to predefine an allocation of Software Components to EcuPartitions in the System Design phase. The final and complete assignment is described in the OS Configuration.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'APPLICATION-PARTITION-TO-ECU-PARTITION-MAPPING'
        self._node = etree.Element('APPLICATION-PARTITION-TO-ECU-PARTITION-MAPPING')
        self.__applicationPartitions = {}
        self.__ecuPartition = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__applicationPartitions = self._resolve_reference_list('{*}APPLICATION-PARTITION-REFS/*', self.__applicationPartitions)
        self.__ecuPartition = self._resolve_single_reference('{*}ECU-PARTITION-REF', self.__ecuPartition)

    def get_applicationPartitions(self) -> list[ApplicationPartition]:
        return list(self.__applicationPartitions.keys())

    def __bind_applicationPartition(self, value: ApplicationPartition) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__applicationPartitions.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ApplicationPartition) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ApplicationPartition or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_applicationPartition(self, value: ApplicationPartition) -> None:
        """
        Adds a single value to the applicationPartitions
        """
        if value is not None:
            self.__bind_applicationPartition(value)
            self.__applicationPartitions[value] = None

    def set_applicationPartitions(self, values: list[ApplicationPartition]) -> None:
        """
        Adds a list of ref value to the applicationPartitions
        """
        for value in values:
            self.add_applicationPartition(value)

    def remove_applicationPartition(self, value: ApplicationPartition) -> None:
        """
        Removes a single value from applicationPartitions
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__applicationPartitions.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_applicationPartitions(self, values: list[ApplicationPartition]) -> None:
        """
        Removes a list of value from applicationPartitions
        """
        for value in values:
            self.remove_applicationPartition(value)

    def get_ecuPartition(self) -> EcuPartition:
        return self.__ecuPartition

    def set_ecuPartition(self, value: EcuPartition) -> None:
        """
        Adds a single value to the ecuPartition
        """
        if value is not None:
            if isinstance(value, EcuPartition) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcuPartition or its sub-classes'.format(value))
            if self.__ecuPartition is not None and self.__ecuPartition.is_proxy() is False:
                self.__ecuPartition.referenced_by.remove(self)
            self.__ecuPartition = value
            value.referenced_by.add(self)
        elif self.__ecuPartition is not None:
            if self.__ecuPartition.is_proxy() is False:
                self.__ecuPartition.referenced_by.remove(self)
            self.__ecuPartition = None
        XDT.mark_dirty(self.__ecuPartition, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the ApplicationPartitionToEcuPartitionMapping.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ApplicationPartitions'] = self.__applicationPartitions
        property_values['EcuPartition'] = self.__ecuPartition
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of ApplicationPartitionToEcuPartitionMapping node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        self._save_reference_list('APPLICATION-PARTITION-REFS', 'APPLICATION-PARTITION-REF', self.__applicationPartitions, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('ECU-PARTITION-REF', self.__ecuPartition, self._insert_after_tags + ['APPLICATION-PARTITION-REFS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['ECU-PARTITION-REF', 'APPLICATION-PARTITION-REFS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

