class NmCluster(Identifiable):
    """
    Set of NM nodes coordinated with use of the NM algorithm.
    """
    def __init__(self):
        super().__init__()
        self.__nmChannelId = None
        self.__nmChannelSleepMaster = None
        self.__nmLightTimeout = None
        self.__nmNodeDetectionEnabled = None
        self.__nmNodeIdEnabled = None
        self.__nmPncParticipation = None
        self.__nmRepeatMsgIndEnabled = None
        self.__nmSynchronizingNetwork = None
        self.__pncClusterVectorLength = None
        self.__communicationCluster = None
        self.__nmNodes = {}
        self.__variationPoint = None
        self.__nmNodes_childTypes = {'CAN-NM-NODE': 'CanNmNode', 'FLEXRAY-NM-NODE': 'FlexrayNmNode', 'UDP-NM-NODE': 'UdpNmNode', 'J-1939-NM-NODE': 'J1939NmNode', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__nmChannelId = self._read_scalar_element('NM-CHANNEL-ID', datatype_utils.get_int_value)
        self.__nmChannelSleepMaster = self._read_scalar_element('NM-CHANNEL-SLEEP-MASTER', datatype_utils.get_bool_value)
        self.__nmLightTimeout = self._read_scalar_element('NM-LIGHT-TIMEOUT', datatype_utils.get_float_value)
        self.__nmNodeDetectionEnabled = self._read_scalar_element('NM-NODE-DETECTION-ENABLED', datatype_utils.get_bool_value)
        self.__nmNodeIdEnabled = self._read_scalar_element('NM-NODE-ID-ENABLED', datatype_utils.get_bool_value)
        self.__nmPncParticipation = self._read_scalar_element('NM-PNC-PARTICIPATION', datatype_utils.get_bool_value)
        self.__nmRepeatMsgIndEnabled = self._read_scalar_element('NM-REPEAT-MSG-IND-ENABLED', datatype_utils.get_bool_value)
        self.__nmSynchronizingNetwork = self._read_scalar_element('NM-SYNCHRONIZING-NETWORK', datatype_utils.get_bool_value)
        self.__pncClusterVectorLength = self._read_scalar_element('PNC-CLUSTER-VECTOR-LENGTH', datatype_utils.get_int_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__nmNodes, '{*}NM-NODES/*', self.__nmNodes_childTypes, file, 'nmNodes', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__communicationCluster = self._resolve_single_reference('{*}COMMUNICATION-CLUSTER-REF', self.__communicationCluster)

