class NmCoordinator(ARObject):
    """
    A NM coordinator is an ECU, which is connected to at least two busses, and where the requirement exists that shutdown of NM of at least two of these busses (also referred to as coordinated busses) has to be performed synchronously.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'NM-COORDINATOR'
        self._node = etree.Element('NM-COORDINATOR')
        self.__index = None
        self.__nmActiveCoordinator = None
        self.__nmCoordSyncSupport = None
        self.__nmGlobalCoordinatorTime = None
        self.__nmShutdownDelayTimer = None
        self.__nmNodes = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__index = self._read_scalar_element('INDEX', datatype_utils.get_int_value)
        self.__nmActiveCoordinator = self._read_scalar_element('NM-ACTIVE-COORDINATOR', datatype_utils.get_bool_value)
        self.__nmCoordSyncSupport = self._read_scalar_element('NM-COORD-SYNC-SUPPORT', datatype_utils.get_bool_value)
        self.__nmGlobalCoordinatorTime = self._read_scalar_element('NM-GLOBAL-COORDINATOR-TIME', datatype_utils.get_float_value)
        self.__nmShutdownDelayTimer = self._read_scalar_element('NM-SHUTDOWN-DELAY-TIMER', datatype_utils.get_float_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__nmNodes = self._resolve_reference_list('{*}NM-NODE-REFS/*', self.__nmNodes)

    def get_index(self) -> int:
        return self.__index

    def set_index(self, value: int) -> None:
        self.__index = value
        XDT.mark_attribute_dirty('index', self)

    def get_nmActiveCoordinator(self) -> bool:
        return self.__nmActiveCoordinator

    def set_nmActiveCoordinator(self, value: bool) -> None:
        self.__nmActiveCoordinator = value
        XDT.mark_attribute_dirty('nmActiveCoordinator', self)

    def get_nmCoordSyncSupport(self) -> bool:
        return self.__nmCoordSyncSupport

    def set_nmCoordSyncSupport(self, value: bool) -> None:
        self.__nmCoordSyncSupport = value
        XDT.mark_attribute_dirty('nmCoordSyncSupport', self)

    def get_nmGlobalCoordinatorTime(self) -> float:
        return self.__nmGlobalCoordinatorTime

    def set_nmGlobalCoordinatorTime(self, value: float) -> None:
        self.__nmGlobalCoordinatorTime = value
        XDT.mark_attribute_dirty('nmGlobalCoordinatorTime', self)

    def get_nmShutdownDelayTimer(self) -> float:
        return self.__nmShutdownDelayTimer

    def set_nmShutdownDelayTimer(self, value: float) -> None:
        self.__nmShutdownDelayTimer = value
        XDT.mark_attribute_dirty('nmShutdownDelayTimer', self)

    def get_nmNodes(self) -> list[NmNode]:
        return list(self.__nmNodes.keys())

    def __bind_nmNode(self, value: NmNode) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__nmNodes.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, NmNode) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NmNode or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_nmNode(self, value: NmNode) -> None:
        """
        Adds a single value to the nmNodes
        """
        if value is not None:
            self.__bind_nmNode(value)
            self.__nmNodes[value] = None

    def set_nmNodes(self, values: list[NmNode]) -> None:
        """
        Adds a list of ref value to the nmNodes
        """
        for value in values:
            self.add_nmNode(value)

    def remove_nmNode(self, value: NmNode) -> None:
        """
        Removes a single value from nmNodes
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__nmNodes.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_nmNodes(self, values: list[NmNode]) -> None:
        """
        Removes a list of value from nmNodes
        """
        for value in values:
            self.remove_nmNode(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Index'] = self.__index
        property_values['NmActiveCoordinator'] = self.__nmActiveCoordinator
        property_values['NmCoordSyncSupport'] = self.__nmCoordSyncSupport
        property_values['NmGlobalCoordinatorTime'] = self.__nmGlobalCoordinatorTime
        property_values['NmShutdownDelayTimer'] = self.__nmShutdownDelayTimer
        property_values['NmNodes'] = self.__nmNodes
        return property_values


    def _save_contents(self):
        """
        Saves the content of NmCoordinator node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_scalar_element('INDEX', 'index', str(self.__index) if self.__index is not None else None, create_after_nodes = ['T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('NM-ACTIVE-COORDINATOR', 'nmActiveCoordinator', ('true' if self.__nmActiveCoordinator is True else 'false') if self.__nmActiveCoordinator is not None else None, create_after_nodes = ['INDEX', 'T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('NM-COORD-SYNC-SUPPORT', 'nmCoordSyncSupport', ('true' if self.__nmCoordSyncSupport is True else 'false') if self.__nmCoordSyncSupport is not None else None, create_after_nodes = ['NM-ACTIVE-COORDINATOR', 'INDEX', 'T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('NM-GLOBAL-COORDINATOR-TIME', 'nmGlobalCoordinatorTime', str(self.__nmGlobalCoordinatorTime) if self.__nmGlobalCoordinatorTime is not None else None, create_after_nodes = ['NM-COORD-SYNC-SUPPORT', 'NM-ACTIVE-COORDINATOR', 'INDEX', 'T', 'S'] + self._insert_after_tags)
        self._save_reference_list('NM-NODE-REFS', 'NM-NODE-REF', self.__nmNodes, self._insert_after_tags + ['NM-GLOBAL-COORDINATOR-TIME', 'NM-COORD-SYNC-SUPPORT', 'NM-ACTIVE-COORDINATOR', 'INDEX', 'T', 'S'])
        self._save_scalar_element('NM-SHUTDOWN-DELAY-TIMER', 'nmShutdownDelayTimer', str(self.__nmShutdownDelayTimer) if self.__nmShutdownDelayTimer is not None else None, create_after_nodes = ['NM-NODE-REFS', 'NM-GLOBAL-COORDINATOR-TIME', 'NM-COORD-SYNC-SUPPORT', 'NM-ACTIVE-COORDINATOR', 'INDEX', 'T', 'S'] + self._insert_after_tags)

class NmClusterCoupling(ARObject):
    """
    Attributes that are valid for each of the referenced (coupled) clusters.
    """
    def __init__(self):
        super().__init__()
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the NmClusterCoupling.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

