class NmConfig(FibexElement,UploadableDesignElement):
    """
    Contains the all configuration elements for AUTOSAR Nm.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'NM-CONFIG'
        self._node = etree.Element('NM-CONFIG')
        self.__nmClusters = {}
        self.__nmClusterCouplings = {}
        self.__nmIfEcus = {}
        self.__nmClusters_childTypes = {'CAN-NM-CLUSTER': 'CanNmCluster', 'FLEXRAY-NM-CLUSTER': 'FlexrayNmCluster', 'J-1939-NM-CLUSTER': 'J1939NmCluster', 'LIN-NM-CLUSTER': 'LinNmCluster', 'UDP-NM-CLUSTER': 'UdpNmCluster', }
        self.__nmClusterCouplings_childTypes = {'CAN-NM-CLUSTER-COUPLING': 'CanNmClusterCoupling', 'FLEXRAY-NM-CLUSTER-COUPLING': 'FlexrayNmClusterCoupling', 'UDP-NM-CLUSTER-COUPLING': 'UdpNmClusterCoupling', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__nmClusters, '{*}NM-CLUSTERS/*', self.__nmClusters_childTypes, file, 'nmClusters', refCounter)
        refCounter = self._build_child_collection(self.__nmClusterCouplings, '{*}NM-CLUSTER-COUPLINGS/*', self.__nmClusterCouplings_childTypes, file, 'nmClusterCouplings', refCounter)
        refCounter = self._build_child_collection(self.__nmIfEcus, '{*}NM-IF-ECUS/*', NmEcu, file, 'nmIfEcus', refCounter)
        return self

    def get_nmClusters(self) -> list[NmCluster]:
        return list(self.__nmClusters.keys())

    def __bind_nmCluster(self, value: NmCluster) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__nmClusters.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, NmCluster) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NmCluster or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'NmCluster_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_nmCluster_at_index(self, index: int, value: NmCluster) -> None:
        """
        Adds a single value to the nmClusters at the given index
        """
        if value is not None:
            self.__bind_nmCluster(value)
            AutosarNode._insert_at_index(self.__nmClusters, value, index)
            self._sync_add_to_merge_target(value)

    def add_nmCluster(self, value: NmCluster) -> None:
        """
        Adds a single value to the nmClusters
        """
        if value is not None:
            self.__bind_nmCluster(value)
            self.__nmClusters[value] = None
            self._sync_add_to_merge_target(value)

    def set_nmClusters(self, values: list[NmCluster]) -> None:
        """
        Adds a list of ref value to the nmClusters
        """
        for value in values:
            self.add_nmCluster(value)

