class DoIpConfig(ARObject):
    """
    This element defines the DoIp configuration for a specific Ecu.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DO-IP-CONFIG'
        self._node = etree.Element('DO-IP-CONFIG')
        self.__doIpProtocolVersion = None
        self.__doipInterfaces = {}
        self.__logicAddress = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__doIpProtocolVersion = self._read_scalar_element('DO-IP-PROTOCOL-VERSION', datatype_utils.get_int_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__doipInterfaces, '{*}DOIP-INTERFACES/*', DoIpInterface, file, 'doipInterfaces', refCounter)
        self.__logicAddress = self._build_single_child('{*}LOGIC-ADDRESS', DoIpLogicAddress, file, 'logicAddress')
        return self

    def get_doIpProtocolVersion(self) -> int:
        return self.__doIpProtocolVersion

    def set_doIpProtocolVersion(self, value: int) -> None:
        self.__doIpProtocolVersion = value
        XDT.mark_attribute_dirty('doIpProtocolVersion', self)

    def get_doipInterfaces(self) -> list[DoIpInterface]:
        return list(self.__doipInterfaces.keys())

    def __bind_doipInterface(self, value: DoIpInterface) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__doipInterfaces.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, DoIpInterface) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DoIpInterface or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'DoIpInterface_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_doipInterface_at_index(self, index: int, value: DoIpInterface) -> None:
        """
        Adds a single value to the doipInterfaces at the given index
        """
        if value is not None:
            self.__bind_doipInterface(value)
            AutosarNode._insert_at_index(self.__doipInterfaces, value, index)
            self._sync_add_to_merge_target(value)

    def add_doipInterface(self, value: DoIpInterface) -> None:
        """
        Adds a single value to the doipInterfaces
        """
        if value is not None:
            self.__bind_doipInterface(value)
            self.__doipInterfaces[value] = None
            self._sync_add_to_merge_target(value)

    def set_doipInterfaces(self, values: list[DoIpInterface]) -> None:
        """
        Adds a list of ref value to the doipInterfaces
        """
        for value in values:
            self.add_doipInterface(value)

    def remove_doipInterface(self, value: DoIpInterface) -> None:
        """
        Removes a single value from doipInterfaces
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_doipInterfaces(self, values: list[DoIpInterface]) -> None:
        """
        Removes a list of value from doipInterfaces
        """
        for value in values:
            self.remove_doipInterface(value)

    def get_logicAddress(self) -> DoIpLogicAddress:
        return self.__logicAddress

    def set_logicAddress(self, value: DoIpLogicAddress) -> None:
        """
        Adds a single value to the logicAddress
        """
        if value is not None:
            if isinstance(value, DoIpLogicAddress) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DoIpLogicAddress or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__logicAddress = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'DoIpLogicAddress_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__logicAddress is not None:
            self.__logicAddress._detach_from_parent()
            self.__logicAddress = None
        XDT.mark_dirty(self.__logicAddress, self)

    def new_DoIpInterface(self, name: str=None) -> DoIpInterface:
        """
        Creates a new DoIpInterface under the DoIpConfig.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DoIpInterface_obj = DoIpInterface()
        if isinstance(DoIpInterface_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DoIpInterface_obj.name = name if isinstance(DoIpInterface_obj, Referrable) else None
        self.add_doipInterface(DoIpInterface_obj)
        if isinstance(DoIpInterface_obj, Referrable):
            DoIpInterface_obj.set_shortName(name)
        return DoIpInterface_obj

    def new_LogicAddress(self, name: str=None) -> DoIpLogicAddress:
        """
        Creates a new DoIpLogicAddress under the DoIpConfig.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DoIpLogicAddress_obj = DoIpLogicAddress()
        if isinstance(DoIpLogicAddress_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DoIpLogicAddress_obj.name = name if isinstance(DoIpLogicAddress_obj, Referrable) else None
        self.set_logicAddress(DoIpLogicAddress_obj)
        if isinstance(DoIpLogicAddress_obj, Referrable):
            DoIpLogicAddress_obj.set_shortName(name)
        return DoIpLogicAddress_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__doipInterfaces)
        if self.__logicAddress is not None:
            children.append(self.__logicAddress)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__doipInterfaces:
            return 'doipInterfaces'
        if self.__logicAddress is child:
            return 'logicAddress'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'doipInterfaces':
            self.__doipInterfaces[child] = None
        elif containment_slot == 'logicAddress':
            if self.__logicAddress is None:
                self.__logicAddress = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'doipInterfaces':
            self.__doipInterfaces.pop(child, None)
        elif containment_slot == 'logicAddress':
            if self.__logicAddress is child:
                self.__logicAddress = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['DoIpProtocolVersion'] = self.__doIpProtocolVersion
        return property_values


    def _save_contents(self):
        """
        Saves the content of DoIpConfig node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_scalar_element('DO-IP-PROTOCOL-VERSION', 'doIpProtocolVersion', str(self.__doIpProtocolVersion) if self.__doIpProtocolVersion is not None else None, create_after_nodes = ['T', 'S'] + self._insert_after_tags)
        self._save_child_collection('DOIP-INTERFACES', None, self.__doipInterfaces, self._insert_after_tags + ['DO-IP-PROTOCOL-VERSION', 'T', 'S'])
        self._save_single_child('LOGIC-ADDRESS', self.__logicAddress, self._insert_after_tags + ['DOIP-INTERFACES', 'DO-IP-PROTOCOL-VERSION', 'T', 'S'])

