class FMFeature(ARElement):
    """
    A FMFeature describes an essential characteristic of a product. Each FMFeature is contained in exactly one FMFeatureModel.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FM-FEATURE'
        self._node = etree.Element('FM-FEATURE')
        self.__maximumIntendedBindingTime = None
        self.__minimumIntendedBindingTime = None
        self.__attributeDefs = {}
        self.__decompositions = {}
        self.__relations = {}
        self.__restrictions = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__maximumIntendedBindingTime = self._read_scalar_element('MAXIMUM-INTENDED-BINDING-TIME', BindingTimeEnum.get)
        self.__minimumIntendedBindingTime = self._read_scalar_element('MINIMUM-INTENDED-BINDING-TIME', BindingTimeEnum.get)

        refCounter = 0
        refCounter = self._build_child_collection(self.__attributeDefs, '{*}ATTRIBUTE-DEFS/*', FMAttributeDef, file, 'attributeDefs', refCounter)
