class FMFeatureRelation(Identifiable):
    """
    Defines relations for FMFeatures, for example dependencies on, other FMFeatures, or conflicts with other FMFeatures. A FMFeature, can only be part of a FMFeatureSelectionSet if all its, relations are fulfilled.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FM-FEATURE-RELATION'
        self._node = etree.Element('FM-FEATURE-RELATION')
        self.__features = {}
        self.__restriction = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__restriction = self._build_single_child('{*}RESTRICTION', FMConditionByFeaturesAndAttributes, file, 'restriction')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__features = self._resolve_reference_list('{*}FEATURE-REFS/*', self.__features)

    def get_features(self) -> list[FMFeature]:
        return list(self.__features.keys())

    def __bind_feature(self, value: FMFeature) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__features.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, FMFeature) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FMFeature or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_feature(self, value: FMFeature) -> None:
        """
        Adds a single value to the features
        """
        if value is not None:
            self.__bind_feature(value)
            self.__features[value] = None

    def set_features(self, values: list[FMFeature]) -> None:
        """
        Adds a list of ref value to the features
        """
        for value in values:
            self.add_feature(value)

    def remove_feature(self, value: FMFeature) -> None:
        """
        Removes a single value from features
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__features.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_features(self, values: list[FMFeature]) -> None:
        """
        Removes a list of value from features
        """
        for value in values:
            self.remove_feature(value)

    def get_restriction(self) -> FMConditionByFeaturesAndAttributes:
        return self.__restriction

    def set_restriction(self, value: FMConditionByFeaturesAndAttributes) -> None:
        """
        Adds a single value to the restriction
        """
        if value is not None:
            if isinstance(value, FMConditionByFeaturesAndAttributes) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FMConditionByFeaturesAndAttributes or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__restriction = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'FMConditionByFeaturesAndAttributes_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__restriction is not None:
            self.__restriction._detach_from_parent()
            self.__restriction = None
        XDT.mark_dirty(self.__restriction, self)

    def new_Restriction(self, name: str=None) -> FMConditionByFeaturesAndAttributes:
        """
        Creates a new FMConditionByFeaturesAndAttributes under the FMFeatureRelation.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        FMConditionByFeaturesAndAttributes_obj = FMConditionByFeaturesAndAttributes()
        if isinstance(FMConditionByFeaturesAndAttributes_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        FMConditionByFeaturesAndAttributes_obj.name = name if isinstance(FMConditionByFeaturesAndAttributes_obj, Referrable) else None
        self.set_restriction(FMConditionByFeaturesAndAttributes_obj)
        if isinstance(FMConditionByFeaturesAndAttributes_obj, Referrable):
            FMConditionByFeaturesAndAttributes_obj.set_shortName(name)
        return FMConditionByFeaturesAndAttributes_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__restriction is not None:
            children.append(self.__restriction)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__restriction is child:
            return 'restriction'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'restriction':
            if self.__restriction is None:
                self.__restriction = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'restriction':
            if self.__restriction is child:
                self.__restriction = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Features'] = self.__features
        return property_values


    def _save_contents(self):
        """
        Saves the content of FMFeatureRelation node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        self._save_reference_list('FEATURE-REFS', 'FEATURE-REF', self.__features, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_child('RESTRICTION', self.__restriction, self._insert_after_tags + ['FEATURE-REFS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

class FMFeatureDecomposition(ARObject):
    """
    A FMFeatureDecomposition describes dependencies between a list of, features and their parent feature (i.e., the FMFeature that, aggregates the FMFeatureDecomposition). The kind of dependency is, defined by the attribute category.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FM-FEATURE-DECOMPOSITION'
        self._node = etree.Element('FM-FEATURE-DECOMPOSITION')
        self.__category = None
        self.__max = None
        self.__min = None
        self.__features = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__category = self._read_scalar_element('CATEGORY', datatype_utils.get_string_value)
        self.__max = self._read_scalar_element('MAX', datatype_utils.get_int_value)
        self.__min = self._read_scalar_element('MIN', datatype_utils.get_int_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__features = self._resolve_reference_list('{*}FEATURE-REFS/*', self.__features)

    def get_category(self) -> str:
        return self.__category

    def set_category(self, value: str) -> None:
        self.__category = value
        XDT.mark_attribute_dirty('category', self)

    def get_max(self) -> int:
        return self.__max

