class ApmcChoiceContainerDef(ApmcContainerDef):
    """
    This meta-class represents the ability to specify a choice-semantics on the container level (on the "definition" side of the target-configuration). , , The choice semantics can be utilized to emulate inheritance in the M1 model.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'APMC-CHOICE-CONTAINER-DEF'
        self._node = etree.Element('APMC-CHOICE-CONTAINER-DEF')
        self.__choices = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__choices, '{*}CHOICES/*', ApmcParamConfContainerDef, file, 'choices', refCounter)
        return self

    def get_choices(self) -> list[ApmcParamConfContainerDef]:
        return list(self.__choices.keys())

    def __bind_choice(self, value: ApmcParamConfContainerDef) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__choices.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ApmcParamConfContainerDef) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ApmcParamConfContainerDef or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'ApmcParamConfContainerDef_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['upperMultiplicityIsInfinite', 'upperMultiplicity', 'lowerMultiplicity', 'elementCreation', 'requiresIndex', 'origin', 'uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_choice_at_index(self, index: int, value: ApmcParamConfContainerDef) -> None:
        """
        Adds a single value to the choices at the given index
        """
        if value is not None:
            self.__bind_choice(value)
            AutosarNode._insert_at_index(self.__choices, value, index)
            self._sync_add_to_merge_target(value)

    def add_choice(self, value: ApmcParamConfContainerDef) -> None:
        """
        Adds a single value to the choices
        """
        if value is not None:
            self.__bind_choice(value)
            self.__choices[value] = None
            self._sync_add_to_merge_target(value)

    def set_choices(self, values: list[ApmcParamConfContainerDef]) -> None:
        """
        Adds a list of ref value to the choices
        """
        for value in values:
            self.add_choice(value)

    def remove_choice(self, value: ApmcParamConfContainerDef) -> None:
        """
        Removes a single value from choices
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
