class ApmcForeignReferenceValue(ApmcAbstractReferenceValue):
    """
    This meta-class represents the ability to establish a flat (as opposed to an instanceRef) reference to model elements out of the context of target-configuration, i.e. in the design model.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'APMC-FOREIGN-REFERENCE-VALUE'
        self._node = etree.Element('APMC-FOREIGN-REFERENCE-VALUE')
        self.__value = None


    def _resolve_references(self):
        super()._resolve_references()
        self.__value = self._resolve_single_reference('{*}VALUE-REF', self.__value)

    def get_value(self) -> Referrable:
        return self.__value

    def set_value(self, value: Referrable) -> None:
        """
        Adds a single value to the value
        """
        if value is not None:
            if isinstance(value, Referrable) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Referrable or its sub-classes'.format(value))
            if self.__value is not None and self.__value.is_proxy() is False:
                self.__value.referenced_by.remove(self)
            self.__value = value
            value.referenced_by.add(self)
        elif self.__value is not None:
            if self.__value.is_proxy() is False:
                self.__value.referenced_by.remove(self)
            self.__value = None
        XDT.mark_dirty(self.__value, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Value'] = self.__value
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of ApmcForeignReferenceValue node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ApmcAbstractReferenceValue()
        self._save_single_reference('VALUE-REF', self.__value, self._insert_after_tags + ['DEFINITION-REF', 'INDEX', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

class ApmcFunctionalClusterValue(UploadablePackageElement,ApmcAbstractValue):
    """
    This class represents the entry point into the configuration of a single functional cluster on the AUTOSAR adaptive platform on the "value" side.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'APMC-FUNCTIONAL-CLUSTER-VALUE'
        self._node = etree.Element('APMC-FUNCTIONAL-CLUSTER-VALUE')
        self.__containers = {}
        self.__definition = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__containers, '{*}CONTAINERS/*', ApmcContainerValue, file, 'containers', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__definition = self._resolve_single_reference('{*}DEFINITION-REF', self.__definition)

    def get_containers(self) -> list[ApmcContainerValue]:
        return list(self.__containers.keys())

    def __bind_container(self, value: ApmcContainerValue) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__containers.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ApmcContainerValue) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ApmcContainerValue or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'ApmcContainerValue_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['index', 'uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_container_at_index(self, index: int, value: ApmcContainerValue) -> None:
        """
        Adds a single value to the containers at the given index
        """
        if value is not None:
            self.__bind_container(value)
            AutosarNode._insert_at_index(self.__containers, value, index)
            self._sync_add_to_merge_target(value)

    def add_container(self, value: ApmcContainerValue) -> None:
        """
        Adds a single value to the containers
        """
        if value is not None:
            self.__bind_container(value)
            self.__containers[value] = None
            self._sync_add_to_merge_target(value)

    def set_containers(self, values: list[ApmcContainerValue]) -> None:
        """
        Adds a list of ref value to the containers
        """
        for value in values:
            self.add_container(value)

    def remove_container(self, value: ApmcContainerValue) -> None:
        """
        Removes a single value from containers
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_containers(self, values: list[ApmcContainerValue]) -> None:
        """
        Removes a list of value from containers
        """
        for value in values:
            self.remove_container(value)

    def get_definition(self) -> ApmcFunctionalClusterDef:
        return self.__definition

    def set_definition(self, value: ApmcFunctionalClusterDef) -> None:
        """
        Adds a single value to the definition
        """
        if value is not None:
            if isinstance(value, ApmcFunctionalClusterDef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ApmcFunctionalClusterDef or its sub-classes'.format(value))
            if self.__definition is not None and self.__definition.is_proxy() is False:
                self.__definition.referenced_by.remove(self)
            self.__definition = value
            value.referenced_by.add(self)
        elif self.__definition is not None:
            if self.__definition.is_proxy() is False:
                self.__definition.referenced_by.remove(self)
            self.__definition = None
        XDT.mark_dirty(self.__definition, self)

    def new_Container(self, name: str=None) -> ApmcContainerValue:
        """
        Creates a new ApmcContainerValue under the ApmcFunctionalClusterValue.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ApmcContainerValue_obj = ApmcContainerValue()
        if isinstance(ApmcContainerValue_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        ApmcContainerValue_obj.name = name if isinstance(ApmcContainerValue_obj, Referrable) else None
        self.add_container(ApmcContainerValue_obj)
        if isinstance(ApmcContainerValue_obj, Referrable):
            ApmcContainerValue_obj.set_shortName(name)
        return ApmcContainerValue_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__containers)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__containers:
            return 'containers'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'containers':
            self.__containers[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'containers':
            self.__containers.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Definition'] = self.__definition
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of ApmcFunctionalClusterValue node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_UploadablePackageElement()
        super()._save_ApmcAbstractValue()
        self._save_child_collection('CONTAINERS', None, self.__containers, self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('DEFINITION-REF', self.__definition, self._insert_after_tags + ['CONTAINERS', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

