class AdaptiveSwcInternalBehavior(Identifiable):
    """
    This meta-class represents the ability to define an internal behavior of an AtomicSwComponentType used on the AUTOSAR adaptive platform. , , Please note that the model of internal behavior in this case, in stark contrast to the situation of the AUTOSAR classic platform, is very minimal.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ADAPTIVE-SWC-INTERNAL-BEHAVIOR'
        self._node = etree.Element('ADAPTIVE-SWC-INTERNAL-BEHAVIOR')
        self.__serviceDependencies = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__serviceDependencies, '{*}SERVICE-DEPENDENCYS/*', SwcServiceDependency, file, 'serviceDependencies', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_serviceDependencies(self) -> list[SwcServiceDependency]:
        return list(self.__serviceDependencies.keys())

    def __bind_serviceDependencie(self, value: SwcServiceDependency) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__serviceDependencies.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, SwcServiceDependency) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwcServiceDependency or its sub-classes'.format(value))

        value._detach_from_parent()
