class PersistencyInterfaceElement(Identifiable):
    """
    This meta-class provides the abstract ability to define an element of a PortInterface for the support of persistency use cases.
    """
    def __init__(self):
        super().__init__()
        self.__updateStrategy = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__updateStrategy = self._read_scalar_element('UPDATE-STRATEGY', PersistencyElementLevelUpdateStrategyEnum.get)

        return self

    def get_updateStrategy(self) -> PersistencyElementLevelUpdateStrategyEnum:
        return self.__updateStrategy

    def set_updateStrategy(self, value: PersistencyElementLevelUpdateStrategyEnum) -> None:
        self.__updateStrategy = value
        XDT.mark_attribute_dirty('updateStrategy', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['UpdateStrategy'] = self.__updateStrategy
        return property_values


    def _save_PersistencyInterfaceElement(self):
        """
        Saves the content of PersistencyInterfaceElement node
        """
        super()._save_Identifiable()
        self._save_scalar_element('UPDATE-STRATEGY', 'updateStrategy', self.__updateStrategy.literal if self.__updateStrategy is not None else None, create_after_nodes = ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)

