class NoSupervision(PhmSupervision):
    """
    Defines explicitly that NO supervision shall be applied for a specific Supervised Entity instance.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'NO-SUPERVISION'
        self._node = etree.Element('NO-SUPERVISION')
        self.__process = None
        self.__targetPhmSupervisedEntity = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__targetPhmSupervisedEntity = self._build_single_child('{*}TARGET-PHM-SUPERVISED-ENTITY-IREF', RPortPrototypeInExecutableInstanceRef, file, 'targetPhmSupervisedEntity')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__process = self._resolve_single_reference('{*}PROCESS-REF', self.__process)

    def get_process(self) -> Process:
        return self.__process

    def set_process(self, value: Process) -> None:
        """
        Adds a single value to the process
        """
        if value is not None:
            if isinstance(value, Process) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Process or its sub-classes'.format(value))
            if self.__process is not None and self.__process.is_proxy() is False:
                self.__process.referenced_by.remove(self)
            self.__process = value
            value.referenced_by.add(self)
        elif self.__process is not None:
            if self.__process.is_proxy() is False:
                self.__process.referenced_by.remove(self)
            self.__process = None
        XDT.mark_dirty(self.__process, self)

