class SupervisionModeCondition(Identifiable):
    """
    This element defines a SupervisionModeCondition in the context of platform health management contribution.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SUPERVISION-MODE-CONDITION'
        self._node = etree.Element('SUPERVISION-MODE-CONDITION')
        self.__stateReferences = {}
        self.__stateReferences_childTypes = {'FUNCTION-GROUP-PHM-STATE-REFERENCE': 'FunctionGroupPhmStateReference', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__stateReferences, '{*}STATE-REFERENCES/*', self.__stateReferences_childTypes, file, 'stateReferences', refCounter)
        return self

    def get_stateReferences(self) -> list[PhmStateReference]:
        return list(self.__stateReferences.keys())

    def __bind_stateReference(self, value: PhmStateReference) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__stateReferences.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, PhmStateReference) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PhmStateReference or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'PhmStateReference_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_stateReference_at_index(self, index: int, value: PhmStateReference) -> None:
        """
        Adds a single value to the stateReferences at the given index
        """
        if value is not None:
            self.__bind_stateReference(value)
            AutosarNode._insert_at_index(self.__stateReferences, value, index)
            self._sync_add_to_merge_target(value)

    def add_stateReference(self, value: PhmStateReference) -> None:
        """
        Adds a single value to the stateReferences
        """
        if value is not None:
            self.__bind_stateReference(value)
            self.__stateReferences[value] = None
            self._sync_add_to_merge_target(value)

    def set_stateReferences(self, values: list[PhmStateReference]) -> None:
        """
        Adds a list of ref value to the stateReferences
        """
        for value in values:
            self.add_stateReference(value)

    def remove_stateReference(self, value: PhmStateReference) -> None:
        """
        Removes a single value from stateReferences
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_stateReferences(self, values: list[PhmStateReference]) -> None:
        """
        Removes a list of value from stateReferences
        """
        for value in values:
            self.remove_stateReference(value)

    def new_FunctionGroupPhmStateReference(self, name: str=None) -> FunctionGroupPhmStateReference:
        """
        Creates a new FunctionGroupPhmStateReference under the SupervisionModeCondition.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        FunctionGroupPhmStateReference_obj = FunctionGroupPhmStateReference()
        if isinstance(FunctionGroupPhmStateReference_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        FunctionGroupPhmStateReference_obj.name = name if isinstance(FunctionGroupPhmStateReference_obj, Referrable) else None
        self.add_stateReference(FunctionGroupPhmStateReference_obj)
        if isinstance(FunctionGroupPhmStateReference_obj, Referrable):
            FunctionGroupPhmStateReference_obj.set_shortName(name)
        return FunctionGroupPhmStateReference_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__stateReferences)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__stateReferences:
            return 'stateReferences'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'stateReferences':
            self.__stateReferences[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'stateReferences':
            self.__stateReferences.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of SupervisionModeCondition node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        self._save_child_collection('STATE-REFERENCES', None, self.__stateReferences, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

