class PersistencyKeyValueStorage(PersistencyDeployment):
    """
    This meta-class represents the ability to model a key-value storage  on target-configuration level.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PERSISTENCY-KEY-VALUE-STORAGE'
        self._node = etree.Element('PERSISTENCY-KEY-VALUE-STORAGE')
        self.__keyValuePairs = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__keyValuePairs, '{*}KEY-VALUE-PAIRS/*', PersistencyKeyValuePair, file, 'keyValuePairs', refCounter)
        return self

    def get_keyValuePairs(self) -> list[PersistencyKeyValuePair]:
        return list(self.__keyValuePairs.keys())

    def __bind_keyValuePair(self, value: PersistencyKeyValuePair) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__keyValuePairs.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, PersistencyKeyValuePair) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PersistencyKeyValuePair or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'PersistencyKeyValuePair_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['updateStrategy', 'uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_keyValuePair_at_index(self, index: int, value: PersistencyKeyValuePair) -> None:
        """
        Adds a single value to the keyValuePairs at the given index
        """
        if value is not None:
            self.__bind_keyValuePair(value)
            AutosarNode._insert_at_index(self.__keyValuePairs, value, index)
            self._sync_add_to_merge_target(value)

    def add_keyValuePair(self, value: PersistencyKeyValuePair) -> None:
        """
        Adds a single value to the keyValuePairs
        """
        if value is not None:
            self.__bind_keyValuePair(value)
            self.__keyValuePairs[value] = None
            self._sync_add_to_merge_target(value)

    def set_keyValuePairs(self, values: list[PersistencyKeyValuePair]) -> None:
        """
        Adds a list of ref value to the keyValuePairs
        """
        for value in values:
            self.add_keyValuePair(value)

    def remove_keyValuePair(self, value: PersistencyKeyValuePair) -> None:
        """
        Removes a single value from keyValuePairs
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_keyValuePairs(self, values: list[PersistencyKeyValuePair]) -> None:
        """
        Removes a list of value from keyValuePairs
        """
        for value in values:
            self.remove_keyValuePair(value)

    def new_KeyValuePair(self, name: str=None) -> PersistencyKeyValuePair:
        """
        Creates a new PersistencyKeyValuePair under the PersistencyKeyValueStorage.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PersistencyKeyValuePair_obj = PersistencyKeyValuePair()
        if isinstance(PersistencyKeyValuePair_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        PersistencyKeyValuePair_obj.name = name if isinstance(PersistencyKeyValuePair_obj, Referrable) else None
        self.add_keyValuePair(PersistencyKeyValuePair_obj)
        if isinstance(PersistencyKeyValuePair_obj, Referrable):
            PersistencyKeyValuePair_obj.set_shortName(name)
        return PersistencyKeyValuePair_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__keyValuePairs)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__keyValuePairs:
            return 'keyValuePairs'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'keyValuePairs':
            self.__keyValuePairs[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'keyValuePairs':
            self.__keyValuePairs.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of PersistencyKeyValueStorage node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_PersistencyDeployment()
        self._save_child_collection('KEY-VALUE-PAIRS', None, self.__keyValuePairs, self._insert_after_tags + ['VERSION', 'UPDATE-STRATEGY', 'REDUNDANCY-HANDLINGS', 'MINIMUM-SUSTAINED-SIZE', 'MAXIMUM-ALLOWED-SIZE', 'DEPLOYMENT-URIS', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

