class ServiceInstanceToPortPrototypeMapping(UploadableDesignElement):
    """
    This meta-class represents the ability to assign a transport layer dependent ServiceInstance to a PortPrototype. , , With this mapping it is possible to define how specific PortPrototypes are represented in the middleware in terms of service configuration.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SERVICE-INSTANCE-TO-PORT-PROTOTYPE-MAPPING'
        self._node = etree.Element('SERVICE-INSTANCE-TO-PORT-PROTOTYPE-MAPPING')
        self.__portPrototype = None
        self.__processDesign = None
        self.__process = None
        self.__serviceInstance = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__portPrototype = self._build_single_child('{*}PORT-PROTOTYPE-IREF', PortPrototypeInExecutableInstanceRef, file, 'portPrototype')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__processDesign = self._resolve_single_reference('{*}PROCESS-DESIGN-REF', self.__processDesign)
        self.__process = self._resolve_single_reference('{*}PROCESS-REF', self.__process)
        self.__serviceInstance = self._resolve_single_reference('{*}SERVICE-INSTANCE-REF', self.__serviceInstance)

    def get_portPrototype(self) -> PortPrototypeInExecutableInstanceRef:
        return self.__portPrototype

    def set_portPrototype(self, value: PortPrototypeInExecutableInstanceRef) -> None:
        """
        Adds a single value to the portPrototype
        """
        if value is not None:
            if isinstance(value, PortPrototypeInExecutableInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PortPrototypeInExecutableInstanceRef or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__portPrototype = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'PortPrototypeInExecutableInstanceRef_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__portPrototype is not None:
            self.__portPrototype._detach_from_parent()
            self.__portPrototype = None
        XDT.mark_dirty(self.__portPrototype, self)

