    def new_PortPrototype(self, name: str=None) -> PortPrototypeInExecutableInstanceRef:
        """
        Creates a new PortPrototypeInExecutableInstanceRef under the ServiceInstanceToPortPrototypeMapping.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PortPrototypeInExecutableInstanceRef_obj = PortPrototypeInExecutableInstanceRef()
        if isinstance(PortPrototypeInExecutableInstanceRef_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        PortPrototypeInExecutableInstanceRef_obj.name = name if isinstance(PortPrototypeInExecutableInstanceRef_obj, Referrable) else None
        self.set_portPrototype(PortPrototypeInExecutableInstanceRef_obj)
