class FunctionGroupSet(AtpClassifier,UploadableDesignElement):
    """
    This meta-class provides the ability to create arbitrary collections of function groups.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FUNCTION-GROUP-SET'
        self._node = etree.Element('FUNCTION-GROUP-SET')
        self.__functionGroups = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__functionGroups, '{*}FUNCTION-GROUPS/*', ModeDeclarationGroupPrototype, file, 'functionGroups', refCounter)
        return self

    def get_functionGroups(self) -> list[ModeDeclarationGroupPrototype]:
        return list(self.__functionGroups.keys())

    def __bind_functionGroup(self, value: ModeDeclarationGroupPrototype) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__functionGroups.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ModeDeclarationGroupPrototype) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ModeDeclarationGroupPrototype or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'ModeDeclarationGroupPrototype_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_functionGroup_at_index(self, index: int, value: ModeDeclarationGroupPrototype) -> None:
        """
        Adds a single value to the functionGroups at the given index
        """
        if value is not None:
            self.__bind_functionGroup(value)
            AutosarNode._insert_at_index(self.__functionGroups, value, index)
            self._sync_add_to_merge_target(value)

    def add_functionGroup(self, value: ModeDeclarationGroupPrototype) -> None:
        """
        Adds a single value to the functionGroups
        """
        if value is not None:
            self.__bind_functionGroup(value)
            self.__functionGroups[value] = None
            self._sync_add_to_merge_target(value)

    def set_functionGroups(self, values: list[ModeDeclarationGroupPrototype]) -> None:
        """
        Adds a list of ref value to the functionGroups
        """
        for value in values:
            self.add_functionGroup(value)

    def remove_functionGroup(self, value: ModeDeclarationGroupPrototype) -> None:
        """
        Removes a single value from functionGroups
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_functionGroups(self, values: list[ModeDeclarationGroupPrototype]) -> None:
        """
        Removes a list of value from functionGroups
        """
        for value in values:
            self.remove_functionGroup(value)

    def new_FunctionGroup(self, name: str=None) -> ModeDeclarationGroupPrototype:
        """
        Creates a new ModeDeclarationGroupPrototype under the FunctionGroupSet.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ModeDeclarationGroupPrototype_obj = ModeDeclarationGroupPrototype()
        if isinstance(ModeDeclarationGroupPrototype_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        ModeDeclarationGroupPrototype_obj.name = name if isinstance(ModeDeclarationGroupPrototype_obj, Referrable) else None
        self.add_functionGroup(ModeDeclarationGroupPrototype_obj)
        if isinstance(ModeDeclarationGroupPrototype_obj, Referrable):
            ModeDeclarationGroupPrototype_obj.set_shortName(name)
        return ModeDeclarationGroupPrototype_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__functionGroups)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__functionGroups:
            return 'functionGroups'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'functionGroups':
            self.__functionGroups[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'functionGroups':
            self.__functionGroups.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of FunctionGroupSet node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_AtpClassifier()
        super()._save_UploadableDesignElement()
        self._save_child_collection('FUNCTION-GROUPS', None, self.__functionGroups, self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

